insert into public.date_catalog (id,title,category,description,objective,duration_minutes,energy,setting,materials,preparation,steps,prompts,low_energy_alternative,accessibility,consent,enjoyment_tips,active,sort_order)
values
  ('01-cafe-largo-sin-celulares', 'Café largo sin celulares', 'conexión-y-conversación', 'Preparen una bebida que ya disfruten y dejen los teléfonos fuera de la mesa durante un rato acordado. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Abrir curiosidad y escucha mutua alrededor de la atención compartida durante un café tranquilo, sin buscar respuestas correctas.', 75, 'baja', 'interior', '["Tazas","Una bebida que ya tengan"]'::jsonb, 'Elijan un rincón cómodo y acuerden si pondrán los teléfonos en silencio o fuera del alcance.', '["Preparen un lugar cómodo y acuerden guardar las pantallas si a ambos les parece bien.","Comiencen con esta idea: Preparen una bebida que ya disfruten y dejen los teléfonos fuera de la mesa durante un rato acordado.","Elijan una pregunta, alternen quién comparte y permitan que cualquiera cambie de tema o pase.","Cierren con un detalle que les gustaría recordar; no hace falta llegar a conclusiones."]'::jsonb, '["¿Qué recuerdo propio se relaciona con la atención compartida durante un café tranquilo?","¿Qué parte de la atención compartida durante un café tranquilo disfrutas más y qué la hace especial para ti?","¿Qué te gustaría preguntarme con curiosidad sobre la atención compartida durante un café tranquilo?","¿Qué idea o gusto reciente te gustaría que yo conociera?","¿Qué respuesta prefieres dejar para otro día?"]'::jsonb, 'Hagan una bebida en casa y conversen durante quince minutos, sin preparar nada más.', '["Pueden hablar, escribir o señalar una pregunta; ajusten ruido, luz y postura a su comodidad.","No conviertan guardar el celular en una regla; ambos pueden revisarlo si lo necesitan."]'::jsonb, '["Cada quien puede pasar una pregunta o cambiar de tema sin explicar por qué."]'::jsonb, 'Dejen que el silencio también forme parte de la conversación y no intenten responder todas las preguntas.', true, 1),
  ('02-desayuno-al-amanecer', 'Desayuno al amanecer', 'conexión-y-conversación', 'Elijan algo sencillo para desayunar mientras observan cómo despierta el día, desde casa o al aire libre. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Abrir curiosidad y escucha mutua alrededor de compartir el inicio del día y sus pequeños rituales, sin buscar respuestas correctas.', 60, 'baja', 'indistinto', '["Alimentos para el desayuno","Vasos o tazas"]'::jsonb, 'La noche anterior acuerden una opción sencilla y preparen solo lo necesario.', '["Preparen un lugar cómodo y acuerden guardar las pantallas si a ambos les parece bien.","Comiencen con esta idea: Elijan algo sencillo para desayunar mientras observan cómo despierta el día, desde casa o al aire libre.","Elijan una pregunta, alternen quién comparte y permitan que cualquiera cambie de tema o pase.","Cierren con un detalle que les gustaría recordar; no hace falta llegar a conclusiones."]'::jsonb, '["¿Qué parte de compartir el inicio del día y sus pequeños rituales disfrutas más y qué la hace especial para ti?","¿Qué te gustaría preguntarme con curiosidad sobre compartir el inicio del día y sus pequeños rituales?","¿Qué idea o gusto reciente te gustaría que yo conociera?","¿Qué respuesta prefieres dejar para otro día?","¿Qué detalle de esta charla te gustaría llevarte?"]'::jsonb, 'Tomen algo caliente junto a una ventana cuando ya estén despiertos, sin madrugar si no les apetece.', '["Pueden hablar, escribir o señalar una pregunta; ajusten ruido, luz y postura a su comodidad.","El amanecer no es una obligación: cambien la hora si el descanso importa más."]'::jsonb, '["Cada quien puede pasar una pregunta o cambiar de tema sin explicar por qué."]'::jsonb, 'Dejen que el silencio también forme parte de la conversación y no intenten responder todas las preguntas.', true, 2),
  ('03-una-libreria-y-nuestras-elecciones', 'Una librería y nuestras elecciones', 'conexión-y-conversación', 'Recorran una librería o una colección de libros que ya tengan; cada quien elige una portada para contar por qué le llamó la atención. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Abrir curiosidad y escucha mutua alrededor de los gustos e historias que elegimos leer, sin buscar respuestas correctas.', 75, 'baja', 'interior', '["Libros disponibles en el lugar"]'::jsonb, 'Acuerden que solo van a mirar y compartir elecciones; no necesitan comprar nada.', '["Preparen un lugar cómodo y acuerden guardar las pantallas si a ambos les parece bien.","Comiencen con esta idea: Recorran una librería o una colección de libros que ya tengan; cada quien elige una portada para contar por qué le llamó la atención.","Elijan una pregunta, alternen quién comparte y permitan que cualquiera cambie de tema o pase.","Cierren con un detalle que les gustaría recordar; no hace falta llegar a conclusiones."]'::jsonb, '["¿Qué te gustaría preguntarme con curiosidad sobre los gustos e historias que elegimos leer?","¿Qué idea o gusto reciente te gustaría que yo conociera?","¿Qué respuesta prefieres dejar para otro día?","¿Qué detalle de esta charla te gustaría llevarte?","¿Qué has disfrutado últimamente cuando tienes un rato para ti?"]'::jsonb, 'Elijan libros de una estantería en casa o compartan portadas desde una biblioteca digital que ya usen.', '["Pueden hablar, escribir o señalar una pregunta; ajusten ruido, luz y postura a su comodidad.","Si el lugar está concurrido o tiene barreras, hagan la versión en casa o en una biblioteca accesible."]'::jsonb, '["Cada quien puede pasar una pregunta o cambiar de tema sin explicar por qué."]'::jsonb, 'Dejen que el silencio también forme parte de la conversación y no intenten responder todas las preguntas.', true, 3),
  ('04-paseo-de-preguntas', 'Paseo de preguntas', 'conexión-y-conversación', 'Elijan un recorrido que ya conozcan y alternen una pregunta ligera con un tramo de paseo en silencio. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Abrir curiosidad y escucha mutua alrededor de conversar mientras caminan a su propio paso, sin buscar respuestas correctas.', 45, 'baja', 'exterior', '["Calzado cómodo","Agua si la necesitan"]'::jsonb, 'Acuerden duración, ruta y una alternativa bajo techo según sus necesidades del día.', '["Preparen un lugar cómodo y acuerden guardar las pantallas si a ambos les parece bien.","Comiencen con esta idea: Elijan un recorrido que ya conozcan y alternen una pregunta ligera con un tramo de paseo en silencio.","Elijan una pregunta, alternen quién comparte y permitan que cualquiera cambie de tema o pase.","Cierren con un detalle que les gustaría recordar; no hace falta llegar a conclusiones."]'::jsonb, '["¿Qué idea o gusto reciente te gustaría que yo conociera?","¿Qué respuesta prefieres dejar para otro día?","¿Qué detalle de esta charla te gustaría llevarte?","¿Qué has disfrutado últimamente cuando tienes un rato para ti?","¿Qué recuerdo propio se relaciona con conversar mientras caminan a su propio paso?"]'::jsonb, 'Hagan el paseo dentro de casa o conviértanlo en una charla sentados.', '["Pueden hablar, escribir o señalar una pregunta; ajusten ruido, luz y postura a su comodidad.","Elijan un trayecto accesible y seguro para ambos; caminar puede sustituirse por cualquier forma cómoda de desplazarse."]'::jsonb, '["Cada quien puede pasar una pregunta o cambiar de tema sin explicar por qué."]'::jsonb, 'Dejen que el silencio también forme parte de la conversación y no intenten responder todas las preguntas.', true, 4),
  ('05-el-museo-de-nuestras-opiniones', 'El museo de nuestras opiniones', 'conexión-y-conversación', 'Elijan tres objetos, imágenes o temas cotidianos y compartan qué opinión les despiertan, sin buscar quién tiene razón. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Abrir curiosidad y escucha mutua alrededor de comparar con humor cómo miramos un mismo tema, sin buscar respuestas correctas.', 60, 'baja', 'indistinto', '["Tres objetos o imágenes que ya tengan"]'::jsonb, 'Seleccionen temas ligeros y acuerden dejar fuera cualquiera que no se sienta cómodo.', '["Preparen un lugar cómodo y acuerden guardar las pantallas si a ambos les parece bien.","Comiencen con esta idea: Elijan tres objetos, imágenes o temas cotidianos y compartan qué opinión les despiertan, sin buscar quién tiene razón.","Elijan una pregunta, alternen quién comparte y permitan que cualquiera cambie de tema o pase.","Cierren con un detalle que les gustaría recordar; no hace falta llegar a conclusiones."]'::jsonb, '["¿Qué respuesta prefieres dejar para otro día?","¿Qué detalle de esta charla te gustaría llevarte?","¿Qué has disfrutado últimamente cuando tienes un rato para ti?","¿Qué recuerdo propio se relaciona con comparar con humor cómo miramos un mismo tema?","¿Qué parte de comparar con humor cómo miramos un mismo tema disfrutas más y qué la hace especial para ti?"]'::jsonb, 'Conversen sobre un solo objeto cotidiano que tengan a la vista.', '["Pueden hablar, escribir o señalar una pregunta; ajusten ruido, luz y postura a su comodidad.","Las diferencias se escuchan con curiosidad; nadie tiene que defender su opinión."]'::jsonb, '["Cada quien puede pasar una pregunta o cambiar de tema sin explicar por qué."]'::jsonb, 'Dejen que el silencio también forme parte de la conversación y no intenten responder todas las preguntas.', true, 5),
  ('06-una-tarde-de-recuerdos-bonitos', 'Una tarde de recuerdos bonitos', 'conexión-y-conversación', 'Elijan algunas fotos u objetos propios y cuenten la historia que cada quien decida compartir. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Abrir curiosidad y escucha mutua alrededor de recordar momentos que cada quien quiera compartir, sin buscar respuestas correctas.', 60, 'baja', 'interior', '["Fotos u objetos personales, opcionales"]'::jsonb, 'Cada quien elige qué mostrar; preparen una opción para conversar sin fotografías.', '["Preparen un lugar cómodo y acuerden guardar las pantallas si a ambos les parece bien.","Comiencen con esta idea: Elijan algunas fotos u objetos propios y cuenten la historia que cada quien decida compartir.","Elijan una pregunta, alternen quién comparte y permitan que cualquiera cambie de tema o pase.","Cierren con un detalle que les gustaría recordar; no hace falta llegar a conclusiones."]'::jsonb, '["¿Qué detalle de esta charla te gustaría llevarte?","¿Qué has disfrutado últimamente cuando tienes un rato para ti?","¿Qué recuerdo propio se relaciona con recordar momentos que cada quien quiera compartir?","¿Qué parte de recordar momentos que cada quien quiera compartir disfrutas más y qué la hace especial para ti?","¿Qué te gustaría preguntarme con curiosidad sobre recordar momentos que cada quien quiera compartir?"]'::jsonb, 'Compartan un recuerdo en voz alta sin buscar objetos ni imágenes.', '["Pueden hablar, escribir o señalar una pregunta; ajusten ruido, luz y postura a su comodidad.","No muestren fotografías de terceras personas ni las suban a la aplicación sin permiso."]'::jsonb, '["Cada quien puede pasar una pregunta o cambiar de tema sin explicar por qué."]'::jsonb, 'Dejen que el silencio también forme parte de la conversación y no intenten responder todas las preguntas.', true, 6),
  ('07-preguntas-que-nunca-nos-hicimos', 'Preguntas que nunca nos hicimos', 'conexión-y-conversación', 'Escriban preguntas ligeras en papeles y tomen turnos para elegir cuáles responder. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Abrir curiosidad y escucha mutua alrededor de descubrir datos, gustos y curiosidades cotidianas, sin buscar respuestas correctas.', 45, 'baja', 'interior', '["Papel","Lápiz"]'::jsonb, 'Cada persona puede proponer preguntas y retirar cualquiera antes de empezar.', '["Preparen un lugar cómodo y acuerden guardar las pantallas si a ambos les parece bien.","Comiencen con esta idea: Escriban preguntas ligeras en papeles y tomen turnos para elegir cuáles responder.","Elijan una pregunta, alternen quién comparte y permitan que cualquiera cambie de tema o pase.","Cierren con un detalle que les gustaría recordar; no hace falta llegar a conclusiones."]'::jsonb, '["¿Qué has disfrutado últimamente cuando tienes un rato para ti?","¿Qué recuerdo propio se relaciona con descubrir datos, gustos y curiosidades cotidianas?","¿Qué parte de descubrir datos, gustos y curiosidades cotidianas disfrutas más y qué la hace especial para ti?","¿Qué te gustaría preguntarme con curiosidad sobre descubrir datos, gustos y curiosidades cotidianas?","¿Qué idea o gusto reciente te gustaría que yo conociera?"]'::jsonb, 'Hagan tres preguntas de palabra y respondan solo las que apetezcan.', '["Pueden hablar, escribir o señalar una pregunta; ajusten ruido, luz y postura a su comodidad.","Mantengan la curiosidad sin convertir las respuestas en una evaluación."]'::jsonb, '["Cada quien puede pasar una pregunta o cambiar de tema sin explicar por qué."]'::jsonb, 'Dejen que el silencio también forme parte de la conversación y no intenten responder todas las preguntas.', true, 7),
  ('08-nuestros-suenos-de-infancia', 'Nuestros sueños de infancia', 'conexión-y-conversación', 'Conversen sobre un deseo o juego de infancia y qué parte todavía les produce alegría o curiosidad. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Abrir curiosidad y escucha mutua alrededor de compartir ilusiones y juegos de cuando éramos pequeños, sin buscar respuestas correctas.', 60, 'baja', 'indistinto', '[]'::jsonb, 'Piensen en un recuerdo que sí quieran contar; no hace falta buscar fotos ni detalles difíciles.', '["Preparen un lugar cómodo y acuerden guardar las pantallas si a ambos les parece bien.","Comiencen con esta idea: Conversen sobre un deseo o juego de infancia y qué parte todavía les produce alegría o curiosidad.","Elijan una pregunta, alternen quién comparte y permitan que cualquiera cambie de tema o pase.","Cierren con un detalle que les gustaría recordar; no hace falta llegar a conclusiones."]'::jsonb, '["¿Qué recuerdo propio se relaciona con compartir ilusiones y juegos de cuando éramos pequeños?","¿Qué parte de compartir ilusiones y juegos de cuando éramos pequeños disfrutas más y qué la hace especial para ti?","¿Qué te gustaría preguntarme con curiosidad sobre compartir ilusiones y juegos de cuando éramos pequeños?","¿Qué idea o gusto reciente te gustaría que yo conociera?","¿Qué respuesta prefieres dejar para otro día?"]'::jsonb, 'Compartan un solo juego o pasatiempo que recuerden con cariño.', '["Pueden hablar, escribir o señalar una pregunta; ajusten ruido, luz y postura a su comodidad.","Los recuerdos pueden ser distintos para cada persona; no hay una versión correcta."]'::jsonb, '["Cada quien puede pasar una pregunta o cambiar de tema sin explicar por qué."]'::jsonb, 'Dejen que el silencio también forme parte de la conversación y no intenten responder todas las preguntas.', true, 8),
  ('09-cartas-para-nuestro-yo-futuro', 'Cartas para nuestro yo futuro', 'conexión-y-conversación', 'Escriban una nota para leer más adelante sobre algo que esperan disfrutar o aprender, sin fijar compromisos. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Abrir curiosidad y escucha mutua alrededor de poner en palabras deseos amables para el futuro, sin buscar respuestas correctas.', 60, 'baja', 'interior', '["Papel","Plumas o lápices","Sobres opcionales"]'::jsonb, 'Acuerden si cada nota será privada o si desean compartirla; la fecha de lectura puede quedar abierta.', '["Preparen un lugar cómodo y acuerden guardar las pantallas si a ambos les parece bien.","Comiencen con esta idea: Escriban una nota para leer más adelante sobre algo que esperan disfrutar o aprender, sin fijar compromisos.","Elijan una pregunta, alternen quién comparte y permitan que cualquiera cambie de tema o pase.","Cierren con un detalle que les gustaría recordar; no hace falta llegar a conclusiones."]'::jsonb, '["¿Qué parte de poner en palabras deseos amables para el futuro disfrutas más y qué la hace especial para ti?","¿Qué te gustaría preguntarme con curiosidad sobre poner en palabras deseos amables para el futuro?","¿Qué idea o gusto reciente te gustaría que yo conociera?","¿Qué respuesta prefieres dejar para otro día?","¿Qué detalle de esta charla te gustaría llevarte?"]'::jsonb, 'Graben una frase de audio para ustedes mismos o piensen el deseo sin guardarlo.', '["Pueden hablar, escribir o señalar una pregunta; ajusten ruido, luz y postura a su comodidad.","No lean ni conserven la nota del otro sin su permiso explícito."]'::jsonb, '["Cada quien puede pasar una pregunta o cambiar de tema sin explicar por qué."]'::jsonb, 'Dejen que el silencio también forme parte de la conversación y no intenten responder todas las preguntas.', true, 9),
  ('10-una-playlist-y-sus-historias', 'Una playlist y sus historias', 'conexión-y-conversación', 'Cada quien propone canciones que ya conoce y cuenta qué recuerdo, sensación o etapa le despierta cada una. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Abrir curiosidad y escucha mutua alrededor de compartir canciones y las razones personales para elegirlas, sin buscar respuestas correctas.', 60, 'baja', 'indistinto', '["Un dispositivo de reproducción","Canciones elegidas por ustedes"]'::jsonb, 'Preparen una selección corta y revisen el volumen para que sea cómodo.', '["Preparen un lugar cómodo y acuerden guardar las pantallas si a ambos les parece bien.","Comiencen con esta idea: Cada quien propone canciones que ya conoce y cuenta qué recuerdo, sensación o etapa le despierta cada una.","Elijan una pregunta, alternen quién comparte y permitan que cualquiera cambie de tema o pase.","Cierren con un detalle que les gustaría recordar; no hace falta llegar a conclusiones."]'::jsonb, '["¿Qué te gustaría preguntarme con curiosidad sobre compartir canciones y las razones personales para elegirlas?","¿Qué idea o gusto reciente te gustaría que yo conociera?","¿Qué respuesta prefieres dejar para otro día?","¿Qué detalle de esta charla te gustaría llevarte?","¿Qué has disfrutado últimamente cuando tienes un rato para ti?"]'::jsonb, 'Elijan una canción y conversen sin reproducirla si prefieren.', '["Pueden hablar, escribir o señalar una pregunta; ajusten ruido, luz y postura a su comodidad.","Compartir una canción no obliga a explicar una historia que alguien quiera mantener privada."]'::jsonb, '["Cada quien puede pasar una pregunta o cambiar de tema sin explicar por qué."]'::jsonb, 'Dejen que el silencio también forme parte de la conversación y no intenten responder todas las preguntas.', true, 10),
  ('11-visitar-nuestros-lugares-favoritos', 'Visitar nuestros lugares favoritos', 'conexión-y-conversación', 'Elijan un lugar conocido por turnos y cuenten qué disfrutan allí; también puede ser un rincón de casa. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Abrir curiosidad y escucha mutua alrededor de conocer qué hace especial un lugar para cada quien, sin buscar respuestas correctas.', 90, 'media', 'exterior', '["Calzado o apoyo de movilidad habitual"]'::jsonb, 'Confirmen que el lugar esté abierto y accesible antes de salir; no hace falta definir un sitio específico desde la app.', '["Preparen un lugar cómodo y acuerden guardar las pantallas si a ambos les parece bien.","Comiencen con esta idea: Elijan un lugar conocido por turnos y cuenten qué disfrutan allí; también puede ser un rincón de casa.","Elijan una pregunta, alternen quién comparte y permitan que cualquiera cambie de tema o pase.","Cierren con un detalle que les gustaría recordar; no hace falta llegar a conclusiones."]'::jsonb, '["¿Qué idea o gusto reciente te gustaría que yo conociera?","¿Qué respuesta prefieres dejar para otro día?","¿Qué detalle de esta charla te gustaría llevarte?","¿Qué has disfrutado últimamente cuando tienes un rato para ti?","¿Qué recuerdo propio se relaciona con conocer qué hace especial un lugar para cada quien?"]'::jsonb, 'Muestren el lugar con una foto propia o describan por qué les gusta.', '["Pueden hablar, escribir o señalar una pregunta; ajusten ruido, luz y postura a su comodidad.","Compartan ubicación solo si ambos quieren y no publiquen la ubicación exacta del otro."]'::jsonb, '["Cada quien puede pasar una pregunta o cambiar de tema sin explicar por qué."]'::jsonb, 'Dejen que el silencio también forme parte de la conversación y no intenten responder todas las preguntas.', true, 11),
  ('12-la-cita-de-escucharnos', 'La cita de escucharnos', 'conexión-y-conversación', 'Elijan un tema cotidiano por turnos: una persona habla unos minutos y la otra escucha, luego cambian si ambos quieren. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Abrir curiosidad y escucha mutua alrededor de practicar una escucha atenta y sin interrupciones, sin buscar respuestas correctas.', 45, 'baja', 'indistinto', '["Un lugar sin demasiadas interrupciones"]'::jsonb, 'Acuerden si quieren recibir preguntas, una respuesta breve o solo ser escuchados.', '["Preparen un lugar cómodo y acuerden guardar las pantallas si a ambos les parece bien.","Comiencen con esta idea: Elijan un tema cotidiano por turnos: una persona habla unos minutos y la otra escucha, luego cambian si ambos quieren.","Elijan una pregunta, alternen quién comparte y permitan que cualquiera cambie de tema o pase.","Cierren con un detalle que les gustaría recordar; no hace falta llegar a conclusiones."]'::jsonb, '["¿Qué respuesta prefieres dejar para otro día?","¿Qué detalle de esta charla te gustaría llevarte?","¿Qué has disfrutado últimamente cuando tienes un rato para ti?","¿Qué recuerdo propio se relaciona con practicar una escucha atenta y sin interrupciones?","¿Qué parte de practicar una escucha atenta y sin interrupciones disfrutas más y qué la hace especial para ti?"]'::jsonb, 'Cada quien comparte una cosa buena y una cosa que le ocupa hoy.', '["Pueden hablar, escribir o señalar una pregunta; ajusten ruido, luz y postura a su comodidad.","Pregunten antes de ofrecer consejos; escuchar no significa tener que resolver."]'::jsonb, '["Cada quien puede pasar una pregunta o cambiar de tema sin explicar por qué."]'::jsonb, 'Dejen que el silencio también forme parte de la conversación y no intenten responder todas las preguntas.', true, 12),
  ('13-lo-que-cambio-en-nosotros', 'Lo que cambió en nosotros', 'conexión-y-conversación', 'Compartan algo que disfrutan, piensan o hacen distinto ahora, sin compararlo con una versión pasada. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Abrir curiosidad y escucha mutua alrededor de actualizarse sobre gustos y costumbres del presente, sin buscar respuestas correctas.', 60, 'baja', 'indistinto', '[]'::jsonb, 'Elijan una pregunta ligera para abrir y dejen el resto a la conversación.', '["Preparen un lugar cómodo y acuerden guardar las pantallas si a ambos les parece bien.","Comiencen con esta idea: Compartan algo que disfrutan, piensan o hacen distinto ahora, sin compararlo con una versión pasada.","Elijan una pregunta, alternen quién comparte y permitan que cualquiera cambie de tema o pase.","Cierren con un detalle que les gustaría recordar; no hace falta llegar a conclusiones."]'::jsonb, '["¿Qué detalle de esta charla te gustaría llevarte?","¿Qué has disfrutado últimamente cuando tienes un rato para ti?","¿Qué recuerdo propio se relaciona con actualizarse sobre gustos y costumbres del presente?","¿Qué parte de actualizarse sobre gustos y costumbres del presente disfrutas más y qué la hace especial para ti?","¿Qué te gustaría preguntarme con curiosidad sobre actualizarse sobre gustos y costumbres del presente?"]'::jsonb, 'Cada quien comparte un gusto nuevo o un hábito que cambió.', '["Pueden hablar, escribir o señalar una pregunta; ajusten ruido, luz y postura a su comodidad.","Hablen desde el presente; nadie tiene que justificar cómo ha cambiado."]'::jsonb, '["Cada quien puede pasar una pregunta o cambiar de tema sin explicar por qué."]'::jsonb, 'Dejen que el silencio también forme parte de la conversación y no intenten responder todas las preguntas.', true, 13),
  ('14-diez-cosas-que-quiero-aprender-de-ti', 'Diez cosas que quiero aprender de ti', 'conexión-y-conversación', 'Cada quien enseña una cosa sencilla que sabe hacer o propone un tema que le gustaría aprender del otro. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Abrir curiosidad y escucha mutua alrededor de intercambiar conocimientos y curiosidades pequeñas, sin buscar respuestas correctas.', 60, 'baja', 'indistinto', '["Materiales sencillos según lo que elijan"]'::jsonb, 'Elijan algo que se pueda mostrar en pocos minutos y que no requiera experiencia previa.', '["Preparen un lugar cómodo y acuerden guardar las pantallas si a ambos les parece bien.","Comiencen con esta idea: Cada quien enseña una cosa sencilla que sabe hacer o propone un tema que le gustaría aprender del otro.","Elijan una pregunta, alternen quién comparte y permitan que cualquiera cambie de tema o pase.","Cierren con un detalle que les gustaría recordar; no hace falta llegar a conclusiones."]'::jsonb, '["¿Qué has disfrutado últimamente cuando tienes un rato para ti?","¿Qué recuerdo propio se relaciona con intercambiar conocimientos y curiosidades pequeñas?","¿Qué parte de intercambiar conocimientos y curiosidades pequeñas disfrutas más y qué la hace especial para ti?","¿Qué te gustaría preguntarme con curiosidad sobre intercambiar conocimientos y curiosidades pequeñas?","¿Qué idea o gusto reciente te gustaría que yo conociera?"]'::jsonb, 'Enseñen una palabra, un truco sencillo o una recomendación personal.', '["Pueden hablar, escribir o señalar una pregunta; ajusten ruido, luz y postura a su comodidad.","Aprender no es examinar: se puede mirar, preguntar o pasar el turno."]'::jsonb, '["Cada quien puede pasar una pregunta o cambiar de tema sin explicar por qué."]'::jsonb, 'Dejen que el silencio también forme parte de la conversación y no intenten responder todas las preguntas.', true, 14),
  ('15-una-conversacion-bajo-las-estrellas', 'Una conversación bajo las estrellas', 'conexión-y-conversación', 'Busquen una vista del cielo desde un lugar cómodo y conversen con pausas para observar, si las condiciones lo permiten. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Abrir curiosidad y escucha mutua alrededor de compartir ideas mientras miran el cielo o la noche, sin buscar respuestas correctas.', 60, 'baja', 'exterior', '["Ropa cómoda según el clima","Manta opcional"]'::jsonb, 'Revisen el clima y elijan una alternativa interior antes de salir.', '["Preparen un lugar cómodo y acuerden guardar las pantallas si a ambos les parece bien.","Comiencen con esta idea: Busquen una vista del cielo desde un lugar cómodo y conversen con pausas para observar, si las condiciones lo permiten.","Elijan una pregunta, alternen quién comparte y permitan que cualquiera cambie de tema o pase.","Cierren con un detalle que les gustaría recordar; no hace falta llegar a conclusiones."]'::jsonb, '["¿Qué recuerdo propio se relaciona con compartir ideas mientras miran el cielo o la noche?","¿Qué parte de compartir ideas mientras miran el cielo o la noche disfrutas más y qué la hace especial para ti?","¿Qué te gustaría preguntarme con curiosidad sobre compartir ideas mientras miran el cielo o la noche?","¿Qué idea o gusto reciente te gustaría que yo conociera?","¿Qué respuesta prefieres dejar para otro día?"]'::jsonb, 'Miren la noche desde una ventana o conversen con una luz tenue en casa.', '["Pueden hablar, escribir o señalar una pregunta; ajusten ruido, luz y postura a su comodidad.","No salgan a un lugar aislado si no les da confianza; observar desde casa también cuenta."]'::jsonb, '["Cada quien puede pasar una pregunta o cambiar de tema sin explicar por qué."]'::jsonb, 'Dejen que el silencio también forme parte de la conversación y no intenten responder todas las preguntas.', true, 15),
  ('16-go-karts', 'Go-karts', 'aventuras-y-diversión', 'Si hay una pista adecuada para ambos, revisen sus reglas y decidan si quieren conducir, mirar o alternar. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de la emoción de conducir y turnarse en una pista, cuidando el ritmo de cada persona.', 60, 'alta', 'interior', '["Calzado cerrado si lo requiere el lugar"]'::jsonb, 'Confirmen directamente requisitos de edad, movilidad, seguridad y acceso; no asuman disponibilidad.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Si hay una pista adecuada para ambos, revisen sus reglas y decidan si quieren conducir, mirar o alternar.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué versión de esta actividad te resultaría divertida?","¿Qué ritmo o papel te gustaría elegir hoy?","¿Qué parte probarías primero y qué prefieres observar?","¿Qué hacemos si uno necesita descansar o cambiar de idea?","¿Qué momento nos dio risa o nos sorprendió?"]'::jsonb, 'Miren juntos una carrera o elijan un juego de conducción accesible que ya tengan.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","Revisen sonido, casco, asiento y transferencia; observar es una participación válida."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar.","Solo suban fotos o videos si ambos y las personas que aparezcan lo aceptan."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 16),
  ('17-parque-de-diversiones', 'Parque de diversiones', 'aventuras-y-diversión', 'Cada persona elige una atracción o zona que le interese; alternen la elección y dejen tiempo para descansar. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de elegir atracciones y compartir una jornada de juego, cuidando el ritmo de cada persona.', 180, 'alta', 'exterior', '["Agua","Protección solar según clima"]'::jsonb, 'Verifiquen horarios, acceso y reglas directamente con el parque antes de planear; armen opciones tranquilas entre actividades.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Cada persona elige una atracción o zona que le interese; alternen la elección y dejen tiempo para descansar.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué ritmo o papel te gustaría elegir hoy?","¿Qué parte probarías primero y qué prefieres observar?","¿Qué hacemos si uno necesita descansar o cambiar de idea?","¿Qué momento nos dio risa o nos sorprendió?","¿Qué reto pequeño sería divertido sin volverlo una competencia?"]'::jsonb, 'Elijan un juego de feria de mesa o hagan una lista de atracciones imaginarias para escoger juntos.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","Tengan presente el ruido, las filas, el clima y las necesidades sensoriales; cambiar el plan está bien."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 17),
  ('18-escape-room', 'Escape room', 'aventuras-y-diversión', 'Elijan una sala que se ajuste al grupo y acuerden que pedir una pista también forma parte del juego. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de resolver pistas de forma colaborativa, cuidando el ritmo de cada persona.', 75, 'media', 'interior', '["Nada imprescindible; el equipo lo define el lugar"]'::jsonb, 'Confirmen accesibilidad, idioma, estímulos, reglas y disponibilidad directamente con el espacio.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Elijan una sala que se ajuste al grupo y acuerden que pedir una pista también forma parte del juego.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué parte probarías primero y qué prefieres observar?","¿Qué hacemos si uno necesita descansar o cambiar de idea?","¿Qué momento nos dio risa o nos sorprendió?","¿Qué reto pequeño sería divertido sin volverlo una competencia?","¿Qué versión de esta actividad te resultaría divertida?"]'::jsonb, 'Resuelvan un acertijo corto en casa o inventen una búsqueda de pistas con objetos.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","Asegúrense de que cualquier encierro simulado o efecto sea aceptable para ambos; pueden salir o pausar."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 18),
  ('19-boliche', 'Boliche', 'aventuras-y-diversión', 'Jueguen una partida relajada: cada quien puede probar una técnica, celebrar los tiros y dejar el marcador en segundo plano. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de coordinar turnos y celebrar intentos sin enfocarse en la puntuación, cuidando el ritmo de cada persona.', 75, 'media', 'interior', '["Calzado adecuado según las reglas del lugar"]'::jsonb, 'Confirmen equipo disponible, accesibilidad y normas del establecimiento; también pueden llevar su propio juego de boliche.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Jueguen una partida relajada: cada quien puede probar una técnica, celebrar los tiros y dejar el marcador en segundo plano.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué hacemos si uno necesita descansar o cambiar de idea?","¿Qué momento nos dio risa o nos sorprendió?","¿Qué reto pequeño sería divertido sin volverlo una competencia?","¿Qué versión de esta actividad te resultaría divertida?","¿Qué ritmo o papel te gustaría elegir hoy?"]'::jsonb, 'Usen botellas vacías y una pelota suave en casa, con espacio despejado.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","Adapten pelota, postura y turnos a cada cuerpo; no hace falta llevar puntuación."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 19),
  ('20-arcade-retro', 'Arcade retro', 'aventuras-y-diversión', 'Elijan juegos de ritmo cómodo, enséñense los controles y cambien de juego cuando deje de ser divertido. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de explorar juegos clásicos por turnos, cuidando el ritmo de cada persona.', 60, 'media', 'interior', '["Fichas o controles solo si ya cuentan con ellos"]'::jsonb, 'Pregunten por opciones accesibles y nivel de sonido directamente en el lugar; no se requiere comprar nada para la versión en casa.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Elijan juegos de ritmo cómodo, enséñense los controles y cambien de juego cuando deje de ser divertido.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué momento nos dio risa o nos sorprendió?","¿Qué reto pequeño sería divertido sin volverlo una competencia?","¿Qué versión de esta actividad te resultaría divertida?","¿Qué ritmo o papel te gustaría elegir hoy?","¿Qué parte probarías primero y qué prefieres observar?"]'::jsonb, 'Jueguen un título retro que ya tengan o hagan un reto de papel por turnos.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","Limiten estímulos o tiempo de pantalla si a alguien le resulta cansado."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 20),
  ('21-patinaje-sobre-hielo', 'Patinaje sobre hielo', 'aventuras-y-diversión', 'Si ambos quieren, practiquen pasos sencillos cerca del borde y descansen cuando lo necesiten. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de probar el equilibrio y apoyarse mutuamente sobre el hielo, cuidando el ritmo de cada persona.', 60, 'alta', 'interior', '["Ropa abrigada","Guantes","Patines según el lugar"]'::jsonb, 'Confirmen condiciones, equipo, apoyos y acceso directamente con la pista.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Si ambos quieren, practiquen pasos sencillos cerca del borde y descansen cuando lo necesiten.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué reto pequeño sería divertido sin volverlo una competencia?","¿Qué versión de esta actividad te resultaría divertida?","¿Qué ritmo o papel te gustaría elegir hoy?","¿Qué parte probarías primero y qué prefieres observar?","¿Qué hacemos si uno necesita descansar o cambiar de idea?"]'::jsonb, 'Hagan una caminata suave o un juego de equilibrio sentado.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","No es necesario patinar: observar, acompañar desde fuera o retirarse son opciones válidas."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 21),
  ('22-senderismo-sencillo', 'Senderismo sencillo', 'aventuras-y-diversión', 'Elijan una ruta de dificultad baja que ambos conozcan o puedan verificar y marquen puntos de descanso, no metas. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de recorrer un camino fácil con pausas para observar, cuidando el ritmo de cada persona.', 90, 'media', 'exterior', '["Agua","Calzado cómodo","Protección climática"]'::jsonb, 'Confirmen condiciones del sendero y el pronóstico; lleven lo necesario para la ruta elegida.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Elijan una ruta de dificultad baja que ambos conozcan o puedan verificar y marquen puntos de descanso, no metas.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué versión de esta actividad te resultaría divertida?","¿Qué ritmo o papel te gustaría elegir hoy?","¿Qué parte probarías primero y qué prefieres observar?","¿Qué hacemos si uno necesita descansar o cambiar de idea?","¿Qué momento nos dio risa o nos sorprendió?"]'::jsonb, 'Paseen por una zona llana o hagan un recorrido breve desde casa.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","Adapten distancia y superficie a la movilidad de ambos; den la vuelta cuando quieran."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 22),
  ('23-paseo-en-bicicleta', 'Paseo en bicicleta', 'aventuras-y-diversión', 'Elijan un tramo conocido y llano; pueden pedalear juntos o turnarse para proponer una parada. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de compartir un trayecto a un ritmo cómodo, cuidando el ritmo de cada persona.', 75, 'media', 'exterior', '["Bicicletas","Casco","Agua"]'::jsonb, 'Revisen bicicletas y ruta; cada persona puede elegir otra forma de acompañar.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Elijan un tramo conocido y llano; pueden pedalear juntos o turnarse para proponer una parada.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué ritmo o papel te gustaría elegir hoy?","¿Qué parte probarías primero y qué prefieres observar?","¿Qué hacemos si uno necesita descansar o cambiar de idea?","¿Qué momento nos dio risa o nos sorprendió?","¿Qué reto pequeño sería divertido sin volverlo una competencia?"]'::jsonb, 'Caminen una vuelta breve o vean una ruta en un mapa sin salir.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","Usen casco y equipo de seguridad; eviten rutas que no resulten cómodas."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 23),
  ('24-golf', 'golf', 'aventuras-y-diversión', 'Practiquen unos golpes sencillos en un espacio apropiado o aprendan una variante de minigolf si les interesa. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de probar golpes recreativos sin esperar dominar la técnica, cuidando el ritmo de cada persona.', 90, 'baja', 'exterior', '["Palos y pelotas solo si el espacio elegido los permite"]'::jsonb, 'Verifiquen reglas, equipamiento y acceso con el lugar; pueden escoger una versión en casa.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Practiquen unos golpes sencillos en un espacio apropiado o aprendan una variante de minigolf si les interesa.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué parte probarías primero y qué prefieres observar?","¿Qué hacemos si uno necesita descansar o cambiar de idea?","¿Qué momento nos dio risa o nos sorprendió?","¿Qué reto pequeño sería divertido sin volverlo una competencia?","¿Qué versión de esta actividad te resultaría divertida?"]'::jsonb, 'Hagan un juego de puntería con objetos suaves en un espacio seguro.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","Adapten el agarre y la postura; no se necesita experiencia ni puntuación."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 24),
  ('25-escalada-indoor', 'Escalada indoor', 'aventuras-y-diversión', 'Si el lugar tiene una ruta inicial adecuada, conversen con el personal y elijan entre escalar o acompañar desde abajo. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de confiar en apoyos y celebrar cada intento, cuidando el ritmo de cada persona.', 90, 'alta', 'interior', '["Equipo de seguridad según el lugar"]'::jsonb, 'Confirmen instructoría, equipo, accesibilidad y requisitos directamente con el gimnasio.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Si el lugar tiene una ruta inicial adecuada, conversen con el personal y elijan entre escalar o acompañar desde abajo.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué hacemos si uno necesita descansar o cambiar de idea?","¿Qué momento nos dio risa o nos sorprendió?","¿Qué reto pequeño sería divertido sin volverlo una competencia?","¿Qué versión de esta actividad te resultaría divertida?","¿Qué ritmo o papel te gustaría elegir hoy?"]'::jsonb, 'Resuelvan un circuito de movimiento suave o armen una ruta de obstáculos sin altura.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","La escalada es opcional; sigan instrucciones profesionales y deténganse ante incomodidad."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 25),
  ('26-juegos-de-mesa-en-cafeteria', 'Juegos de mesa en cafetería', 'aventuras-y-diversión', 'Elijan un juego fácil de explicar, acuerden si quieren cooperar o competir amistosamente y cambien las reglas si lo disfrutan más. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de cooperar o reírse con un juego breve, cuidando el ritmo de cada persona.', 75, 'baja', 'interior', '["Un juego de mesa que ya tengan"]'::jsonb, 'Lleven un juego propio o confirmen si el espacio permite jugar; es válida la versión en casa.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Elijan un juego fácil de explicar, acuerden si quieren cooperar o competir amistosamente y cambien las reglas si lo disfrutan más.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué momento nos dio risa o nos sorprendió?","¿Qué reto pequeño sería divertido sin volverlo una competencia?","¿Qué versión de esta actividad te resultaría divertida?","¿Qué ritmo o papel te gustaría elegir hoy?","¿Qué parte probarías primero y qué prefieres observar?"]'::jsonb, 'Jueguen una ronda corta de cartas o palabras en casa.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","Elijan piezas, letra y duración cómodas; pueden terminar antes de acabar la partida."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 26),
  ('27-karaoke-privado', 'Karaoke privado', 'aventuras-y-diversión', 'Elijan canciones por turnos y permitan cantar a dúo, escuchar o pasar sin que nadie tenga que actuar. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de compartir música, cantar o simplemente escuchar, cuidando el ritmo de cada persona.', 60, 'media', 'interior', '["Lista de canciones que ya conozcan"]'::jsonb, 'Confirmen privacidad, accesibilidad y condiciones del espacio directamente; una sala privada no se da por disponible.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Elijan canciones por turnos y permitan cantar a dúo, escuchar o pasar sin que nadie tenga que actuar.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué reto pequeño sería divertido sin volverlo una competencia?","¿Qué versión de esta actividad te resultaría divertida?","¿Qué ritmo o papel te gustaría elegir hoy?","¿Qué parte probarías primero y qué prefieres observar?","¿Qué hacemos si uno necesita descansar o cambiar de idea?"]'::jsonb, 'Pongan una canción en casa y hagan playback, canten o solo escuchen.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","No graben ni compartan la voz o imagen del otro sin permiso."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 27),
  ('28-busqueda-del-tesoro-por-la-ciudad', 'Búsqueda del tesoro por la ciudad', 'aventuras-y-diversión', 'Escriban pistas para encontrar detalles públicos y seguros, como un color o una forma, sin fotografiar ni acercarse a desconocidos. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de mirar el entorno con curiosidad y resolver pistas juntos, cuidando el ritmo de cada persona.', 90, 'media', 'exterior', '["Papel","Lápiz","Teléfono opcional para orientarse"]'::jsonb, 'Diseñen un recorrido breve por zonas conocidas y accesibles; no incluyan domicilios ni ubicaciones privadas.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Escriban pistas para encontrar detalles públicos y seguros, como un color o una forma, sin fotografiar ni acercarse a desconocidos.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué versión de esta actividad te resultaría divertida?","¿Qué ritmo o papel te gustaría elegir hoy?","¿Qué parte probarías primero y qué prefieres observar?","¿Qué hacemos si uno necesita descansar o cambiar de idea?","¿Qué momento nos dio risa o nos sorprendió?"]'::jsonb, 'Hagan una búsqueda de objetos por habitaciones de casa.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","No publiquen ubicaciones exactas ni fotografíen a personas sin su consentimiento."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 28),
  ('29-un-destino-elegido-al-azar', 'Un destino elegido al azar', 'aventuras-y-diversión', 'Escriban tres tipos de plan que a ambos les parezcan bien, sorteen uno y decidan juntos el destino concreto. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de dejarse sorprender con una opción aprobada por ambos, cuidando el ritmo de cada persona.', 90, 'media', 'indistinto', '["Papelitos o una moneda"]'::jsonb, 'Definan antes opciones, límites prácticos y el derecho de veto; no usen ubicaciones aleatorias ni lugares no verificados.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Escriban tres tipos de plan que a ambos les parezcan bien, sorteen uno y decidan juntos el destino concreto.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué ritmo o papel te gustaría elegir hoy?","¿Qué parte probarías primero y qué prefieres observar?","¿Qué hacemos si uno necesita descansar o cambiar de idea?","¿Qué momento nos dio risa o nos sorprendió?","¿Qué reto pequeño sería divertido sin volverlo una competencia?"]'::jsonb, 'Sortear una receta, juego o rincón de casa para explorar.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","El azar nunca elige por ustedes un traslado, gasto, lugar aislado o actividad incómoda."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 29),
  ('30-zoologico-o-acuario', 'Zoológico o acuario', 'aventuras-y-diversión', 'Recorran solo las áreas que les interesen, respeten las normas del recinto y tomen descansos. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de observar animales y conversar sobre lo que llama la atención, cuidando el ritmo de cada persona.', 120, 'media', 'exterior', '["Calzado cómodo","Agua"]'::jsonb, 'Revisen acceso, recorrido y condiciones actuales directamente con el recinto; no se asume un lugar específico.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Recorran solo las áreas que les interesen, respeten las normas del recinto y tomen descansos.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué parte probarías primero y qué prefieres observar?","¿Qué hacemos si uno necesita descansar o cambiar de idea?","¿Qué momento nos dio risa o nos sorprendió?","¿Qué reto pequeño sería divertido sin volverlo una competencia?","¿Qué versión de esta actividad te resultaría divertida?"]'::jsonb, 'Miren un documental o ilustraciones sobre una especie que ambos elijan.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","Respeten las barreras y el bienestar animal; eviten flashes y zonas de alta estimulación si incomodan."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 30),
  ('31-parque-de-trampolines', 'Parque de trampolines', 'aventuras-y-diversión', 'Si el sitio ofrece una zona adecuada, prueben movimientos sencillos o elijan un rol de observación y descanso. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de jugar con movimiento solo hasta donde cada quien quiera, cuidando el ritmo de cada persona.', 60, 'alta', 'interior', '["Ropa cómoda","Calcetines requeridos por el lugar"]'::jsonb, 'Revisen reglas, restricciones, equipo y accesibilidad directamente con el espacio.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Si el sitio ofrece una zona adecuada, prueben movimientos sencillos o elijan un rol de observación y descanso.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué hacemos si uno necesita descansar o cambiar de idea?","¿Qué momento nos dio risa o nos sorprendió?","¿Qué reto pequeño sería divertido sin volverlo una competencia?","¿Qué versión de esta actividad te resultaría divertida?","¿Qué ritmo o papel te gustaría elegir hoy?"]'::jsonb, 'Hagan estiramientos suaves o una secuencia de movimientos de bajo impacto en casa.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","La actividad no es adecuada para todos los cuerpos; participar mirando también es válido."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 31),
  ('32-tiro-con-arco-recreativo', 'Tiro con arco recreativo', 'aventuras-y-diversión', 'En un espacio supervisado, conozcan el equipo y las instrucciones antes de decidir si desean probar. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de practicar atención y turnos con supervisión, cuidando el ritmo de cada persona.', 60, 'media', 'exterior', '["Equipo proporcionado o indicado por el instructor"]'::jsonb, 'Confirmen supervisión, requisitos, equipo y accesibilidad; nunca improvisen con arcos fuera de un lugar autorizado.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: En un espacio supervisado, conozcan el equipo y las instrucciones antes de decidir si desean probar.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué momento nos dio risa o nos sorprendió?","¿Qué reto pequeño sería divertido sin volverlo una competencia?","¿Qué versión de esta actividad te resultaría divertida?","¿Qué ritmo o papel te gustaría elegir hoy?","¿Qué parte probarías primero y qué prefieres observar?"]'::jsonb, 'Hagan un juego de puntería con saquitos suaves y un blanco amplio.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","Sigan instrucciones profesionales y mantengan distancia segura; cualquiera puede observar o detenerse."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 32),
  ('33-un-recorrido-turistico-diferente', 'Un recorrido turístico diferente', 'aventuras-y-diversión', 'Elijan un tema para observar —arquitectura, árboles o historias públicas— y recorran un área conocida a su ritmo. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de redescubrir una zona cercana mirando detalles nuevos, cuidando el ritmo de cada persona.', 90, 'baja', 'exterior', '["Agua","Calzado cómodo"]'::jsonb, 'Verifiquen acceso del espacio y el trayecto; diseñen el recorrido sin depender de una visita guiada disponible.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Elijan un tema para observar —arquitectura, árboles o historias públicas— y recorran un área conocida a su ritmo.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué reto pequeño sería divertido sin volverlo una competencia?","¿Qué versión de esta actividad te resultaría divertida?","¿Qué ritmo o papel te gustaría elegir hoy?","¿Qué parte probarías primero y qué prefieres observar?","¿Qué hacemos si uno necesita descansar o cambiar de idea?"]'::jsonb, 'Elijan una calle familiar en un mapa y descubran un detalle desde casa.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","Manténganse en zonas públicas seguras y compartan ubicación solo si ambos lo deciden."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 33),
  ('34-experiencia-de-realidad-virtual', 'Experiencia de realidad virtual', 'aventuras-y-diversión', 'Elijan una experiencia corta, observen cómo se siente cada quien y cambien a modo sentado o de observación cuando lo prefieran. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de explorar un entorno virtual por turnos, cuidando el ritmo de cada persona.', 60, 'media', 'interior', '["Equipo de realidad virtual si ya está disponible"]'::jsonb, 'Verifiquen la compatibilidad, el espacio despejado y los controles; no se presupone que tengan un visor.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Elijan una experiencia corta, observen cómo se siente cada quien y cambien a modo sentado o de observación cuando lo prefieran.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué versión de esta actividad te resultaría divertida?","¿Qué ritmo o papel te gustaría elegir hoy?","¿Qué parte probarías primero y qué prefieres observar?","¿Qué hacemos si uno necesita descansar o cambiar de idea?","¿Qué momento nos dio risa o nos sorprendió?"]'::jsonb, 'Exploren juntos una experiencia interactiva en una pantalla que ya tengan.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","Acordar pausas; detengan la experiencia ante mareo, fatiga visual o incomodidad."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 34),
  ('35-un-dia-de-actividades-sorpresa', 'Un día de actividades sorpresa', 'aventuras-y-diversión', 'Cada quien aporta una actividad breve a una lista acordada y eligen una por sorteo; la sorpresa está en el orden, no en los límites. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir novedad y diversión alrededor de crear pequeñas sorpresas que ambos hayan aprobado de antemano, cuidando el ritmo de cada persona.', 120, 'media', 'indistinto', '["Papelitos con ideas que ambos aprobaron"]'::jsonb, 'Acordar duración, opciones, accesibilidad y un veto sin preguntas antes de sortear.', '["Antes de empezar, revisen reglas, accesibilidad, equipo y condiciones actuales del lugar elegido; no den por hecho que una actividad está disponible.","Elijan juntos una versión de la idea: Cada quien aporta una actividad breve a una lista acordada y eligen una por sorteo; la sorpresa está en el orden, no en los límites.","Acuerden turnos, descansos y una señal sencilla para pausar o cambiar de plan.","Al terminar, compartan qué les sorprendió; no hace falta competir ni repetir."]'::jsonb, '["¿Qué ritmo o papel te gustaría elegir hoy?","¿Qué parte probarías primero y qué prefieres observar?","¿Qué hacemos si uno necesita descansar o cambiar de idea?","¿Qué momento nos dio risa o nos sorprendió?","¿Qué reto pequeño sería divertido sin volverlo una competencia?"]'::jsonb, 'Sortear dos juegos o canciones que ya estén en casa.', '["Confirmen accesibilidad, ruido, movilidad, equipo y reglas directamente con el lugar; elijan una alternativa si no se adapta.","Nada de ubicaciones secretas, contacto físico, fotos o compromisos no aceptados previamente."]'::jsonb, '["Cada participante decide si realiza, observa o pausa la actividad; sigan las indicaciones de seguridad del lugar."]'::jsonb, 'La aventura puede adaptarse: observar, descansar o cambiar de actividad es parte del plan.', true, 35),
  ('36-cocinar-pasta-desde-cero', 'Cocinar pasta desde cero', 'complicidad-y-equipo', 'Preparen una masa sencilla y elijan una forma de pasta que puedan hacer con las herramientas que ya tienen. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de coordinarse para preparar masa y darle forma, disfrutando el proceso más que un resultado perfecto.', 100, 'media', 'interior', '["Harina","Agua","Tazón","Superficie limpia"]'::jsonb, 'Revisen ingredientes y restricciones alimentarias; organicen un espacio de trabajo seguro.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Preparen una masa sencilla y elijan una forma de pasta que puedan hacer con las herramientas que ya tienen.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Qué paso de esta actividad te gustaría aprender o guiar?","¿Cómo repartimos los pasos para que ambos estemos cómodos?","¿Qué toque propio te gustaría añadir?","¿Qué hacemos si algo sale distinto a lo esperado?","¿Qué disfrutaste del proceso, sin medir el resultado?"]'::jsonb, 'Den forma a una pasta lista o preparen una salsa para acompañarla.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","Adapten el amasado y cuidado con agua caliente; las tareas pueden repartirse de otra manera."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 36),
  ('37-preparar-sushi-juntos', 'Preparar sushi juntos', 'complicidad-y-equipo', 'Cada persona propone rellenos que sí le apetezcan y armen piezas sencillas alternando quién prepara y quién enrolla. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de armar piezas combinando ingredientes y preferencias, disfrutando el proceso más que un resultado perfecto.', 90, 'media', 'interior', '["Arroz para sushi o arroz disponible","Rellenos elegidos por ustedes"]'::jsonb, 'Laven los ingredientes y acuerden una versión vegetariana o cocida si así lo prefieren.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Cada persona propone rellenos que sí le apetezcan y armen piezas sencillas alternando quién prepara y quién enrolla.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Cómo repartimos los pasos para que ambos estemos cómodos?","¿Qué toque propio te gustaría añadir?","¿Qué hacemos si algo sale distinto a lo esperado?","¿Qué disfrutaste del proceso, sin medir el resultado?","¿Qué pequeño paso podríamos probar en equipo la próxima vez?"]'::jsonb, 'Preparen un bowl con arroz y los mismos ingredientes sin enrollar.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","No se requiere pescado crudo; revisen alergias y manipulen alimentos con cuidado."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 37),
  ('38-clase-de-ceramica', 'Clase de cerámica', 'complicidad-y-equipo', 'Si encuentran una sesión adecuada, prueben una forma sencilla o acompáñense observando; en casa pueden usar material moldeable seguro. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de probar formas con las manos y observar el proceso creativo, disfrutando el proceso más que un resultado perfecto.', 90, 'media', 'interior', '["Arcilla o material moldeable apto para la actividad"]'::jsonb, 'Verifiquen acceso, ventilación y materiales con el espacio elegido; no se supone disponibilidad de clase.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Si encuentran una sesión adecuada, prueben una forma sencilla o acompáñense observando; en casa pueden usar material moldeable seguro.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Qué toque propio te gustaría añadir?","¿Qué hacemos si algo sale distinto a lo esperado?","¿Qué disfrutaste del proceso, sin medir el resultado?","¿Qué pequeño paso podríamos probar en equipo la próxima vez?","¿Qué paso de esta actividad te gustaría aprender o guiar?"]'::jsonb, 'Moldeen una figura con masa reutilizable o plastilina que ya tengan.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","Revisen polvo, limpieza y sensibilidad a materiales; cada quien puede elegir observar."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 38),
  ('39-pintar-un-cuadro-entre-dos', 'Pintar un cuadro entre dos', 'complicidad-y-equipo', 'Empiecen con un tema sencillo; alternen trazos o dividan el lienzo y acuerden cómo unir las partes. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de crear una imagen compartida alternando decisiones, disfrutando el proceso más que un resultado perfecto.', 75, 'baja', 'interior', '["Papel o lienzo","Pinturas o lápices"]'::jsonb, 'Protejan la mesa y elijan materiales lavables si eso les da tranquilidad.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Empiecen con un tema sencillo; alternen trazos o dividan el lienzo y acuerden cómo unir las partes.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Qué hacemos si algo sale distinto a lo esperado?","¿Qué disfrutaste del proceso, sin medir el resultado?","¿Qué pequeño paso podríamos probar en equipo la próxima vez?","¿Qué paso de esta actividad te gustaría aprender o guiar?","¿Cómo repartimos los pasos para que ambos estemos cómodos?"]'::jsonb, 'Dibujen en una hoja compartida con un solo lápiz de color.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","Usen herramientas de agarre cómodo y eviten materiales que irriten o manchen espacios delicados."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 39),
  ('40-armar-un-lego', 'Armar un LEGO', 'complicidad-y-equipo', 'Elijan piezas disponibles, propongan una idea y alternen quién añade una parte a la construcción. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de construir juntos sin seguir necesariamente un manual, disfrutando el proceso más que un resultado perfecto.', 75, 'baja', 'interior', '["Piezas de construcción que ya tengan"]'::jsonb, 'Despejen una mesa y acuerden si seguirán instrucciones o improvisarán.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Elijan piezas disponibles, propongan una idea y alternen quién añade una parte a la construcción.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Qué disfrutaste del proceso, sin medir el resultado?","¿Qué pequeño paso podríamos probar en equipo la próxima vez?","¿Qué paso de esta actividad te gustaría aprender o guiar?","¿Cómo repartimos los pasos para que ambos estemos cómodos?","¿Qué toque propio te gustaría añadir?"]'::jsonb, 'Construyan algo pequeño con bloques grandes, cajas o papel.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","Si las piezas pequeñas son difíciles de manipular, elijan objetos más grandes o participen diseñando."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 40),
  ('41-preparar-una-cena-tematica', 'Preparar una cena temática', 'complicidad-y-equipo', 'Elijan un tema sencillo y asignen tareas opcionales: preparar comida, poner la mesa o elegir música. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de inventar en equipo un ambiente alrededor de una idea elegida, disfrutando el proceso más que un resultado perfecto.', 90, 'media', 'interior', '["Ingredientes ya disponibles","Elementos decorativos opcionales"]'::jsonb, 'Acuerden el tema y revisen restricciones alimentarias; no hace falta comprar ni decorar.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Elijan un tema sencillo y asignen tareas opcionales: preparar comida, poner la mesa o elegir música.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Qué pequeño paso podríamos probar en equipo la próxima vez?","¿Qué paso de esta actividad te gustaría aprender o guiar?","¿Cómo repartimos los pasos para que ambos estemos cómodos?","¿Qué toque propio te gustaría añadir?","¿Qué hacemos si algo sale distinto a lo esperado?"]'::jsonb, 'Den a la cena un nombre divertido usando lo que ya tengan.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","Mantengan los adornos y la preparación opcionales; prioricen seguridad en cocina."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 41),
  ('42-hornear-un-pastel', 'Hornear un pastel', 'complicidad-y-equipo', 'Elijan una receta conocida, lean juntos los pasos y turnen tareas de mezcla y decoración. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de repartirse pasos y esperar juntos el resultado, disfrutando el proceso más que un resultado perfecto.', 120, 'media', 'interior', '["Ingredientes de una receta elegida","Molde","Utensilios de cocina"]'::jsonb, 'Revisen alergias e ingredientes antes; precalienten y manejen el horno con cuidado.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Elijan una receta conocida, lean juntos los pasos y turnen tareas de mezcla y decoración.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Qué paso de esta actividad te gustaría aprender o guiar?","¿Cómo repartimos los pasos para que ambos estemos cómodos?","¿Qué toque propio te gustaría añadir?","¿Qué hacemos si algo sale distinto a lo esperado?","¿Qué disfrutaste del proceso, sin medir el resultado?"]'::jsonb, 'Decoren una fruta o galletas ya preparadas.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","El horno lo maneja quien se sienta cómodo; una alternativa sin hornear también cuenta."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 42),
  ('43-una-receta-con-ingredientes-sorpresa', 'Una receta con ingredientes sorpresa', 'complicidad-y-equipo', 'Cada quien elige un ingrediente apto y conocido; combínenlos en una receta sencilla sin incluir nada que alguien no quiera probar. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de improvisar juntos con alimentos que ambos acepten, disfrutando el proceso más que un resultado perfecto.', 75, 'media', 'interior', '["Ingredientes elegidos y aprobados por ambos","Utensilios habituales"]'::jsonb, 'Revisen alergias, caducidad y método de cocción; la sorpresa es la combinación acordada.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Cada quien elige un ingrediente apto y conocido; combínenlos en una receta sencilla sin incluir nada que alguien no quiera probar.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Cómo repartimos los pasos para que ambos estemos cómodos?","¿Qué toque propio te gustaría añadir?","¿Qué hacemos si algo sale distinto a lo esperado?","¿Qué disfrutaste del proceso, sin medir el resultado?","¿Qué pequeño paso podríamos probar en equipo la próxima vez?"]'::jsonb, 'Elijan dos ingredientes comunes y propongan una combinación imaginaria.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","No introduzcan alimentos desconocidos, alergénicos o rechazados como reto."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 43),
  ('44-plantar-nuestras-propias-flores', 'Plantar nuestras propias flores', 'complicidad-y-equipo', 'Seleccionen una planta adecuada al espacio que ya tienen y repártanse tareas de preparación y cuidado inicial. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de elegir y cuidar una planta colaborativamente, disfrutando el proceso más que un resultado perfecto.', 75, 'baja', 'exterior', '["Maceta","Sustrato","Planta o semillas adecuadas"]'::jsonb, 'Revisen el espacio y las necesidades de cuidado antes de elegir; una planta existente puede servir.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Seleccionen una planta adecuada al espacio que ya tienen y repártanse tareas de preparación y cuidado inicial.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Qué toque propio te gustaría añadir?","¿Qué hacemos si algo sale distinto a lo esperado?","¿Qué disfrutaste del proceso, sin medir el resultado?","¿Qué pequeño paso podríamos probar en equipo la próxima vez?","¿Qué paso de esta actividad te gustaría aprender o guiar?"]'::jsonb, 'Dibujen una maceta o preparen un rincón para una planta que ya tengan.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","Usen guantes si lo prefieren y consulten si alguna planta puede ser tóxica para mascotas."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 44),
  ('45-resolver-un-rompecabezas-grande', 'Resolver un rompecabezas grande', 'complicidad-y-equipo', 'Clasifiquen bordes, colores o zonas y decidan si trabajan en una misma sección o en partes separadas. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de combinar estrategias para avanzar pieza a pieza, disfrutando el proceso más que un resultado perfecto.', 90, 'baja', 'interior', '["Rompecabezas que ya tengan","Mesa despejada"]'::jsonb, 'Asegúrense de tener una superficie donde pueda quedarse sin estorbar.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Clasifiquen bordes, colores o zonas y decidan si trabajan en una misma sección o en partes separadas.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Qué hacemos si algo sale distinto a lo esperado?","¿Qué disfrutaste del proceso, sin medir el resultado?","¿Qué pequeño paso podríamos probar en equipo la próxima vez?","¿Qué paso de esta actividad te gustaría aprender o guiar?","¿Cómo repartimos los pasos para que ambos estemos cómodos?"]'::jsonb, 'Resuelvan una sección pequeña o un acertijo de pocas piezas.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","Alternen tareas visuales y pausas; no es necesario terminarlo hoy."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 45),
  ('46-construir-algo-artesanal', 'Construir algo artesanal', 'complicidad-y-equipo', 'Elijan un objeto pequeño y seguro para crear con materiales reutilizables, turnando diseño y armado. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de transformar materiales sencillos en una creación compartida, disfrutando el proceso más que un resultado perfecto.', 90, 'media', 'interior', '["Cartón o materiales limpios disponibles","Tijeras seguras","Adhesivo"]'::jsonb, 'Definan un proyecto simple y preparen una superficie fácil de limpiar.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Elijan un objeto pequeño y seguro para crear con materiales reutilizables, turnando diseño y armado.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Qué disfrutaste del proceso, sin medir el resultado?","¿Qué pequeño paso podríamos probar en equipo la próxima vez?","¿Qué paso de esta actividad te gustaría aprender o guiar?","¿Cómo repartimos los pasos para que ambos estemos cómodos?","¿Qué toque propio te gustaría añadir?"]'::jsonb, 'Hagan un boceto conjunto sin construirlo todavía.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","Eviten herramientas cortantes o calientes si alguien no está cómodo; sustituyan por materiales seguros."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 46),
  ('47-aprender-un-baile-juntos', 'Aprender un baile juntos', 'complicidad-y-equipo', 'Elijan una canción que ambos acepten y aprendan unos pasos sencillos o inventen movimientos propios. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de explorar ritmo y coordinación con movimientos cómodos, disfrutando el proceso más que un resultado perfecto.', 60, 'media', 'interior', '["Música elegida por ustedes","Espacio despejado"]'::jsonb, 'Despejen el área y decidan si prefieren aprender un paso o solo moverse libremente.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Elijan una canción que ambos acepten y aprendan unos pasos sencillos o inventen movimientos propios.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Qué pequeño paso podríamos probar en equipo la próxima vez?","¿Qué paso de esta actividad te gustaría aprender o guiar?","¿Cómo repartimos los pasos para que ambos estemos cómodos?","¿Qué toque propio te gustaría añadir?","¿Qué hacemos si algo sale distinto a lo esperado?"]'::jsonb, 'Practiquen un movimiento de brazos sentados o escuchen la canción.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","El contacto físico no es necesario; cada persona marca su distancia y rango de movimiento."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 47),
  ('48-preparar-un-picnic-entre-los-dos', 'Preparar un picnic entre los dos', 'complicidad-y-equipo', 'Elijan juntos qué alimentos llevar y quién se encarga de cada detalle, o improvisen una manta en casa. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de organizar una comida sencilla compartiendo decisiones, disfrutando el proceso más que un resultado perfecto.', 90, 'baja', 'indistinto', '["Manta","Comida elegida","Agua"]'::jsonb, 'Revisen clima, sombra y accesibilidad si salen; la versión en interiores también vale.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Elijan juntos qué alimentos llevar y quién se encarga de cada detalle, o improvisen una manta en casa.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Qué paso de esta actividad te gustaría aprender o guiar?","¿Cómo repartimos los pasos para que ambos estemos cómodos?","¿Qué toque propio te gustaría añadir?","¿Qué hacemos si algo sale distinto a lo esperado?","¿Qué disfrutaste del proceso, sin medir el resultado?"]'::jsonb, 'Hagan un picnic en el piso o la mesa con algo que ya tengan.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","Elijan una superficie y asiento cómodos; no es necesario sentarse en el suelo."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 48),
  ('49-disenar-un-juego-de-mesa', 'Diseñar un juego de mesa', 'complicidad-y-equipo', 'Inventen un objetivo, unas pocas reglas y un modo de avanzar con papel, fichas o dibujos; prueben una ronda y editen lo que no funcione. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de crear reglas simples y probarlas en equipo, disfrutando el proceso más que un resultado perfecto.', 90, 'media', 'interior', '["Papel","Lápices","Fichas u objetos pequeños opcionales"]'::jsonb, 'Pongan un límite breve a la primera versión para que no se vuelva una tarea.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Inventen un objetivo, unas pocas reglas y un modo de avanzar con papel, fichas o dibujos; prueben una ronda y editen lo que no funcione.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Cómo repartimos los pasos para que ambos estemos cómodos?","¿Qué toque propio te gustaría añadir?","¿Qué hacemos si algo sale distinto a lo esperado?","¿Qué disfrutaste del proceso, sin medir el resultado?","¿Qué pequeño paso podríamos probar en equipo la próxima vez?"]'::jsonb, 'Diseñen solo una pregunta o carta para un juego futuro.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","Usen letra legible, símbolos claros y piezas fáciles de mover para ambos."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 49),
  ('50-crear-nuestras-propias-velas', 'Crear nuestras propias velas', 'complicidad-y-equipo', 'Si usan un kit adecuado, definan el diseño y alternen las tareas; sigan instrucciones del fabricante y mantengan el calor bajo supervisión. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de elegir formas, colores o aromas para un objeto artesanal, disfrutando el proceso más que un resultado perfecto.', 90, 'media', 'interior', '["Kit de velas adecuado","Superficie resistente al calor"]'::jsonb, 'Revisen instrucciones, ventilación y equipo de seguridad; no improvisen con cera caliente.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Si usan un kit adecuado, definan el diseño y alternen las tareas; sigan instrucciones del fabricante y mantengan el calor bajo supervisión.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Qué toque propio te gustaría añadir?","¿Qué hacemos si algo sale distinto a lo esperado?","¿Qué disfrutaste del proceso, sin medir el resultado?","¿Qué pequeño paso podríamos probar en equipo la próxima vez?","¿Qué paso de esta actividad te gustaría aprender o guiar?"]'::jsonb, 'Diseñen etiquetas o portavelas de papel para una vela ya terminada.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","El vertido caliente requiere supervisión y distancia; quien no quiera manipularlo puede diseñar o mirar."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 50),
  ('51-clase-de-fotografia', 'Clase de fotografía', 'complicidad-y-equipo', 'Elijan un tema y tomen turnos para proponer encuadres con el teléfono o cámara que ya tengan. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de mirar la luz y encuadrar cosas cotidianas, disfrutando el proceso más que un resultado perfecto.', 60, 'baja', 'indistinto', '["Teléfono o cámara que ya tengan"]'::jsonb, 'Acuerden un tema que no requiera fotografiar a desconocidos ni espacios privados.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Elijan un tema y tomen turnos para proponer encuadres con el teléfono o cámara que ya tengan.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Qué hacemos si algo sale distinto a lo esperado?","¿Qué disfrutaste del proceso, sin medir el resultado?","¿Qué pequeño paso podríamos probar en equipo la próxima vez?","¿Qué paso de esta actividad te gustaría aprender o guiar?","¿Cómo repartimos los pasos para que ambos estemos cómodos?"]'::jsonb, 'Encuadren objetos de casa o describan una foto que les gustaría tomar.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","Eviten fotos de personas sin permiso y ajusten brillo o pantalla si resulta incómodo."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 51),
  ('52-aprender-un-idioma-por-una-tarde', 'Aprender un idioma por una tarde', 'complicidad-y-equipo', 'Elijan unas palabras comunes, practíquenlas por turnos y utilícenlas en una mini escena sin corregirse de forma estricta. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de enseñarse expresiones sencillas por juego, disfrutando el proceso más que un resultado perfecto.', 60, 'baja', 'interior', '["Papel o herramienta de consulta que ya usen"]'::jsonb, 'Elijan un idioma o expresiones que les despierten curiosidad y preparen pocas palabras.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Elijan unas palabras comunes, practíquenlas por turnos y utilícenlas en una mini escena sin corregirse de forma estricta.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Qué disfrutaste del proceso, sin medir el resultado?","¿Qué pequeño paso podríamos probar en equipo la próxima vez?","¿Qué paso de esta actividad te gustaría aprender o guiar?","¿Cómo repartimos los pasos para que ambos estemos cómodos?","¿Qué toque propio te gustaría añadir?"]'::jsonb, 'Aprendan una sola frase o jueguen a nombrar objetos de la habitación.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","La pronunciación no se evalúa; mantengan el humor amable y permitan pasar."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 52),
  ('53-preparar-un-postre-nuevo', 'Preparar un postre nuevo', 'complicidad-y-equipo', 'Elijan un postre sencillo que ambos quieran probar y alternen preparación, presentación y degustación. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de descubrir una combinación dulce colaborando, disfrutando el proceso más que un resultado perfecto.', 75, 'media', 'interior', '["Ingredientes de una receta elegida","Utensilios habituales"]'::jsonb, 'Revisen alergias y elijan una receta que se pueda adaptar.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Elijan un postre sencillo que ambos quieran probar y alternen preparación, presentación y degustación.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Qué pequeño paso podríamos probar en equipo la próxima vez?","¿Qué paso de esta actividad te gustaría aprender o guiar?","¿Cómo repartimos los pasos para que ambos estemos cómodos?","¿Qué toque propio te gustaría añadir?","¿Qué hacemos si algo sale distinto a lo esperado?"]'::jsonb, 'Combinen fruta o ingredientes listos en una presentación nueva.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","No presionen a probar un ingrediente; una preparación distinta también cuenta."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 53),
  ('54-disenar-un-pequeno-proyecto-juntos', 'Diseñar un pequeño proyecto juntos', 'complicidad-y-equipo', 'Elijan una idea concreta y acotada, hagan un boceto y definan un primer paso que puedan realizar hoy o dejar anotado. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de imaginar y dividir un proyecto pequeño que puedan pausar, disfrutando el proceso más que un resultado perfecto.', 60, 'baja', 'indistinto', '["Papel","Lápiz","Materiales solo si deciden construir"]'::jsonb, 'Busquen una idea que quepa en una conversación; no hace falta fijar fechas ni comprometerse.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Elijan una idea concreta y acotada, hagan un boceto y definan un primer paso que puedan realizar hoy o dejar anotado.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Qué paso de esta actividad te gustaría aprender o guiar?","¿Cómo repartimos los pasos para que ambos estemos cómodos?","¿Qué toque propio te gustaría añadir?","¿Qué hacemos si algo sale distinto a lo esperado?","¿Qué disfrutaste del proceso, sin medir el resultado?"]'::jsonb, 'Hagan solo un boceto o una lista de opciones para después.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","El proyecto es una posibilidad, no un acuerdo vinculante ni una medida de compromiso."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 54),
  ('55-organizar-una-salida-colaborativa', 'Organizar una salida colaborativa', 'complicidad-y-equipo', 'Propongan una actividad principal y una alternativa tranquila; cada persona añade una preferencia y pueden dejar la fecha para otro momento. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Practicar colaboración alrededor de armar juntos un plan flexible con opciones y descansos, disfrutando el proceso más que un resultado perfecto.', 45, 'baja', 'indistinto', '["Papel o calendario personal opcional"]'::jsonb, 'Anoten accesibilidad, duración aproximada y preferencias; no decidan nada que alguien no quiera.', '["Reúnan lo que ya tienen y decidan juntos qué resultado sería suficiente para disfrutarlo.","Dividan o alternen tareas para llevar a cabo la idea: Propongan una actividad principal y una alternativa tranquila; cada persona añade una preferencia y pueden dejar la fecha para otro momento.","Pausen a mitad para revisar si desean seguir igual, cambiar de rol o simplificar.","Compartan qué aporte del otro les gustó; ordenar o terminar puede quedar para después."]'::jsonb, '["¿Cómo repartimos los pasos para que ambos estemos cómodos?","¿Qué toque propio te gustaría añadir?","¿Qué hacemos si algo sale distinto a lo esperado?","¿Qué disfrutaste del proceso, sin medir el resultado?","¿Qué pequeño paso podríamos probar en equipo la próxima vez?"]'::jsonb, 'Hagan una lista de tres ideas sin tener que escoger hoy.', '["Adapten herramientas, altura de la mesa, agarre y pausas; nadie necesita completar todos los pasos.","Mantengan el plan opcional; cualquiera puede cambiarlo o posponerlo."]'::jsonb, '["Pregunten antes de corregir, dirigir o tocar el trabajo de la otra persona."]'::jsonb, 'El proceso vale más que terminar: pueden cambiar el diseño, guardar a medias o dejar la limpieza para otro momento.', true, 55),
  ('56-picnic-al-atardecer', 'Picnic al atardecer', 'romance-y-detalles', 'Elijan un lugar cómodo o un rincón de casa y compartan una comida sencilla mirando el atardecer si se alcanza a ver. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Crear un momento afectuoso alrededor de compartir una pausa mientras cambia la luz, sin suponer que alguien debe corresponder de cierta manera.', 75, 'baja', 'indistinto', '["Manta o mantel opcional","Comida ya elegida","Agua"]'::jsonb, 'Revisen clima, sombra, asientos y acceso; acuerden una alternativa interior.', '["Elijan juntos el ambiente y pregunten qué tipo de gesto, cercanía o recuerdo sería bienvenido hoy.","Preparen una versión sencilla de la idea: Elijan un lugar cómodo o un rincón de casa y compartan una comida sencilla mirando el atardecer si se alcanza a ver.","Durante el momento, revisen si el ritmo y la propuesta siguen resultando cómodos para ambos.","Cierren con un gesto de agradecimiento o simplemente con una despedida amable, según lo que cada quien prefiera."]'::jsonb, '["¿Qué detalle de este momento te resulta agradable?","¿Qué ambiente te acomoda hoy: conversación, silencio o música?","¿Qué gesto sería bienvenido y cuál prefieres dejar opcional?","¿Qué te gustaría recordar de este rato, si te apetece compartirlo?","¿Prefieres elegir juntos cada detalle o dejar algunas cosas sencillas?"]'::jsonb, 'Miren la luz de tarde desde una ventana mientras comparten una bebida.', '["Adapten iluminación, aroma, postura y volumen; eviten flores o fragancias que puedan causar molestias.","No necesitan salir a un lugar aislado; elijan un asiento cómodo."]'::jsonb, '["Pregunten antes de contacto físico, fotografías o gestos sorpresa; todo puede ser opcional."]'::jsonb, 'Los detalles no llevan expectativas: acuerden cercanía, fotos y gestos; el plan puede terminar en una conversación tranquila.', true, 56),
  ('57-cena-con-flores', 'Cena con flores', 'romance-y-detalles', 'Pongan una flor o elemento natural que ya tengan y compartan una cena sencilla; pueden decidir si cocinar o servir algo listo. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Crear un momento afectuoso alrededor de cuidar juntos un detalle en la mesa, sin suponer que alguien debe corresponder de cierta manera.', 90, 'baja', 'interior', '["Flor opcional","Vajilla habitual"]'::jsonb, 'Comprueben si aromas o polen son cómodos; cualquier decoración es opcional.', '["Elijan juntos el ambiente y pregunten qué tipo de gesto, cercanía o recuerdo sería bienvenido hoy.","Preparen una versión sencilla de la idea: Pongan una flor o elemento natural que ya tengan y compartan una cena sencilla; pueden decidir si cocinar o servir algo listo.","Durante el momento, revisen si el ritmo y la propuesta siguen resultando cómodos para ambos.","Cierren con un gesto de agradecimiento o simplemente con una despedida amable, según lo que cada quien prefiera."]'::jsonb, '["¿Qué ambiente te acomoda hoy: conversación, silencio o música?","¿Qué gesto sería bienvenido y cuál prefieres dejar opcional?","¿Qué te gustaría recordar de este rato, si te apetece compartirlo?","¿Prefieres elegir juntos cada detalle o dejar algunas cosas sencillas?","¿Qué plan pequeño te gustaría repetir a tu manera?"]'::jsonb, 'Adornen la mesa con un dibujo o servilleta de color.', '["Adapten iluminación, aroma, postura y volumen; eviten flores o fragancias que puedan causar molestias.","Pregunten si las flores o fragancias son bienvenidas; no se espera ningún regalo."]'::jsonb, '["Pregunten antes de contacto físico, fotografías o gestos sorpresa; todo puede ser opcional."]'::jsonb, 'Los detalles no llevan expectativas: acuerden cercanía, fotos y gestos; el plan puede terminar en una conversación tranquila.', true, 57),
  ('58-noche-para-ver-estrellas', 'Noche para ver estrellas', 'romance-y-detalles', 'Si el cielo está despejado, miren desde un sitio cómodo e identifiquen figuras propias sin necesidad de conocer constelaciones. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Crear un momento afectuoso alrededor de observar el cielo en calma y compartir lo que imaginan, sin suponer que alguien debe corresponder de cierta manera.', 60, 'baja', 'exterior', '["Ropa cómoda según clima","Manta opcional"]'::jsonb, 'Revisen clima y visibilidad y elijan de antemano una opción desde casa.', '["Elijan juntos el ambiente y pregunten qué tipo de gesto, cercanía o recuerdo sería bienvenido hoy.","Preparen una versión sencilla de la idea: Si el cielo está despejado, miren desde un sitio cómodo e identifiquen figuras propias sin necesidad de conocer constelaciones.","Durante el momento, revisen si el ritmo y la propuesta siguen resultando cómodos para ambos.","Cierren con un gesto de agradecimiento o simplemente con una despedida amable, según lo que cada quien prefiera."]'::jsonb, '["¿Qué gesto sería bienvenido y cuál prefieres dejar opcional?","¿Qué te gustaría recordar de este rato, si te apetece compartirlo?","¿Prefieres elegir juntos cada detalle o dejar algunas cosas sencillas?","¿Qué plan pequeño te gustaría repetir a tu manera?","¿Qué detalle de este momento te resulta agradable?"]'::jsonb, 'Miren el cielo desde una ventana o conversen con luz baja.', '["Adapten iluminación, aroma, postura y volumen; eviten flores o fragancias que puedan causar molestias.","Prioricen un lugar seguro y accesible; observar el cielo no requiere salir."]'::jsonb, '["Pregunten antes de contacto físico, fotografías o gestos sorpresa; todo puede ser opcional."]'::jsonb, 'Los detalles no llevan expectativas: acuerden cercanía, fotos y gestos; el plan puede terminar en una conversación tranquila.', true, 58),
  ('59-cartas-escritas-a-mano', 'Cartas escritas a mano', 'romance-y-detalles', 'Cada quien puede escribir una nota breve sobre un momento agradable o una cualidad que aprecia, y decidir libremente si la comparte. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Crear un momento afectuoso alrededor de expresar aprecio o curiosidad con palabras propias, sin suponer que alguien debe corresponder de cierta manera.', 45, 'baja', 'interior', '["Papel","Plumas"]'::jsonb, 'Acuerden si las cartas se leerán en voz alta, se intercambiarán o serán privadas.', '["Elijan juntos el ambiente y pregunten qué tipo de gesto, cercanía o recuerdo sería bienvenido hoy.","Preparen una versión sencilla de la idea: Cada quien puede escribir una nota breve sobre un momento agradable o una cualidad que aprecia, y decidir libremente si la comparte.","Durante el momento, revisen si el ritmo y la propuesta siguen resultando cómodos para ambos.","Cierren con un gesto de agradecimiento o simplemente con una despedida amable, según lo que cada quien prefiera."]'::jsonb, '["¿Qué te gustaría recordar de este rato, si te apetece compartirlo?","¿Prefieres elegir juntos cada detalle o dejar algunas cosas sencillas?","¿Qué plan pequeño te gustaría repetir a tu manera?","¿Qué detalle de este momento te resulta agradable?","¿Qué ambiente te acomoda hoy: conversación, silencio o música?"]'::jsonb, 'Escriban una frase o guarden la idea sin papel.', '["Adapten iluminación, aroma, postura y volumen; eviten flores o fragancias que puedan causar molestias.","No hay obligación de escribir, entregar ni conservar una carta."]'::jsonb, '["Pregunten antes de contacto físico, fotografías o gestos sorpresa; todo puede ser opcional."]'::jsonb, 'Los detalles no llevan expectativas: acuerden cercanía, fotos y gestos; el plan puede terminar en una conversación tranquila.', true, 59),
  ('60-un-jardin-botanico', 'Un jardín botánico', 'romance-y-detalles', 'Elijan unas pocas plantas que les llamen la atención y cuenten qué colores, formas o recuerdos les evocan. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Crear un momento afectuoso alrededor de recorrer un espacio verde y observar plantas con curiosidad, sin suponer que alguien debe corresponder de cierta manera.', 90, 'baja', 'exterior', '["Calzado cómodo","Agua"]'::jsonb, 'Confirmen acceso, ruta y condiciones directamente con el jardín elegido.', '["Elijan juntos el ambiente y pregunten qué tipo de gesto, cercanía o recuerdo sería bienvenido hoy.","Preparen una versión sencilla de la idea: Elijan unas pocas plantas que les llamen la atención y cuenten qué colores, formas o recuerdos les evocan.","Durante el momento, revisen si el ritmo y la propuesta siguen resultando cómodos para ambos.","Cierren con un gesto de agradecimiento o simplemente con una despedida amable, según lo que cada quien prefiera."]'::jsonb, '["¿Prefieres elegir juntos cada detalle o dejar algunas cosas sencillas?","¿Qué plan pequeño te gustaría repetir a tu manera?","¿Qué detalle de este momento te resulta agradable?","¿Qué ambiente te acomoda hoy: conversación, silencio o música?","¿Qué gesto sería bienvenido y cuál prefieres dejar opcional?"]'::jsonb, 'Observen una planta en casa o miren ilustraciones que ya tengan.', '["Adapten iluminación, aroma, postura y volumen; eviten flores o fragancias que puedan causar molestias.","Elijan un recorrido accesible y respeten las plantas; no es necesario tocar ni oler nada."]'::jsonb, '["Pregunten antes de contacto físico, fotografías o gestos sorpresa; todo puede ser opcional."]'::jsonb, 'Los detalles no llevan expectativas: acuerden cercanía, fotos y gestos; el plan puede terminar en una conversación tranquila.', true, 60),
  ('61-un-concierto-especial', 'Un concierto especial', 'romance-y-detalles', 'Si hay un evento que ambos quieran, acuerden cómo disfrutarlo; también pueden elegir un concierto grabado que ya conozcan. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Crear un momento afectuoso alrededor de compartir música en vivo o escuchar una selección con atención, sin suponer que alguien debe corresponder de cierta manera.', 120, 'media', 'indistinto', '["Protección auditiva opcional","Música elegida"]'::jsonb, 'Verifiquen disponibilidad, acceso y condiciones del evento directamente; la versión en casa no depende de una cartelera.', '["Elijan juntos el ambiente y pregunten qué tipo de gesto, cercanía o recuerdo sería bienvenido hoy.","Preparen una versión sencilla de la idea: Si hay un evento que ambos quieran, acuerden cómo disfrutarlo; también pueden elegir un concierto grabado que ya conozcan.","Durante el momento, revisen si el ritmo y la propuesta siguen resultando cómodos para ambos.","Cierren con un gesto de agradecimiento o simplemente con una despedida amable, según lo que cada quien prefiera."]'::jsonb, '["¿Qué plan pequeño te gustaría repetir a tu manera?","¿Qué detalle de este momento te resulta agradable?","¿Qué ambiente te acomoda hoy: conversación, silencio o música?","¿Qué gesto sería bienvenido y cuál prefieres dejar opcional?","¿Qué te gustaría recordar de este rato, si te apetece compartirlo?"]'::jsonb, 'Escuchen una presentación grabada a volumen cómodo.', '["Adapten iluminación, aroma, postura y volumen; eviten flores o fragancias que puedan causar molestias.","Acordar volumen, salida y pausas; nadie tiene que quedarse en un ambiente ruidoso."]'::jsonb, '["Pregunten antes de contacto físico, fotografías o gestos sorpresa; todo puede ser opcional."]'::jsonb, 'Los detalles no llevan expectativas: acuerden cercanía, fotos y gestos; el plan puede terminar en una conversación tranquila.', true, 61),
  ('62-una-pelicula-elegida-mutuamente', 'Una película elegida mutuamente', 'romance-y-detalles', 'Cada quien propone una película que ya conoce o una categoría; escojan una opción que ambos acepten y pueden pausar para conversar. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Crear un momento afectuoso alrededor de negociar una elección y compartir una pausa audiovisual, sin suponer que alguien debe corresponder de cierta manera.', 120, 'baja', 'interior', '["Pantalla","Película disponible para ustedes"]'::jsonb, 'Acordar duración, subtítulos y género antes; no se asume que un título esté disponible en una plataforma.', '["Elijan juntos el ambiente y pregunten qué tipo de gesto, cercanía o recuerdo sería bienvenido hoy.","Preparen una versión sencilla de la idea: Cada quien propone una película que ya conoce o una categoría; escojan una opción que ambos acepten y pueden pausar para conversar.","Durante el momento, revisen si el ritmo y la propuesta siguen resultando cómodos para ambos.","Cierren con un gesto de agradecimiento o simplemente con una despedida amable, según lo que cada quien prefiera."]'::jsonb, '["¿Qué detalle de este momento te resulta agradable?","¿Qué ambiente te acomoda hoy: conversación, silencio o música?","¿Qué gesto sería bienvenido y cuál prefieres dejar opcional?","¿Qué te gustaría recordar de este rato, si te apetece compartirlo?","¿Prefieres elegir juntos cada detalle o dejar algunas cosas sencillas?"]'::jsonb, 'Vean un corto o compartan una escena que ya tengan.', '["Adapten iluminación, aroma, postura y volumen; eviten flores o fragancias que puedan causar molestias.","Elijan volumen, subtítulos y contenido cómodos; cualquiera puede pausar o parar."]'::jsonb, '["Pregunten antes de contacto físico, fotografías o gestos sorpresa; todo puede ser opcional."]'::jsonb, 'Los detalles no llevan expectativas: acuerden cercanía, fotos y gestos; el plan puede terminar en una conversación tranquila.', true, 62),
  ('63-un-paseo-con-flores', 'Un paseo con flores', 'romance-y-detalles', 'Recorran una zona verde conocida y elijan flores que observen, sin cortarlas ni recogerlas. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Crear un momento afectuoso alrededor de mirar colores y compartir una caminata tranquila, sin suponer que alguien debe corresponder de cierta manera.', 45, 'baja', 'exterior', '["Calzado cómodo"]'::jsonb, 'Revisen clima y accesibilidad; si hay alergias, elijan otra forma de paseo.', '["Elijan juntos el ambiente y pregunten qué tipo de gesto, cercanía o recuerdo sería bienvenido hoy.","Preparen una versión sencilla de la idea: Recorran una zona verde conocida y elijan flores que observen, sin cortarlas ni recogerlas.","Durante el momento, revisen si el ritmo y la propuesta siguen resultando cómodos para ambos.","Cierren con un gesto de agradecimiento o simplemente con una despedida amable, según lo que cada quien prefiera."]'::jsonb, '["¿Qué ambiente te acomoda hoy: conversación, silencio o música?","¿Qué gesto sería bienvenido y cuál prefieres dejar opcional?","¿Qué te gustaría recordar de este rato, si te apetece compartirlo?","¿Prefieres elegir juntos cada detalle o dejar algunas cosas sencillas?","¿Qué plan pequeño te gustaría repetir a tu manera?"]'::jsonb, 'Miren flores desde una ventana o compartan dibujos.', '["Adapten iluminación, aroma, postura y volumen; eviten flores o fragancias que puedan causar molestias.","Eviten fragancias o polen si generan molestias y mantengan el recorrido accesible."]'::jsonb, '["Pregunten antes de contacto físico, fotografías o gestos sorpresa; todo puede ser opcional."]'::jsonb, 'Los detalles no llevan expectativas: acuerden cercanía, fotos y gestos; el plan puede terminar en una conversación tranquila.', true, 63),
  ('64-una-noche-de-postres', 'Una noche de postres', 'romance-y-detalles', 'Elijan entre postres que ya tengan o preparen una porción pequeña para compartir, si ambos quieren. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Crear un momento afectuoso alrededor de probar o compartir sabores dulces sin prisa, sin suponer que alguien debe corresponder de cierta manera.', 60, 'baja', 'indistinto', '["Postre elegido por ustedes","Platos o cucharas"]'::jsonb, 'Revisen alergias y preferencias; no hace falta cocinar ni terminar una porción.', '["Elijan juntos el ambiente y pregunten qué tipo de gesto, cercanía o recuerdo sería bienvenido hoy.","Preparen una versión sencilla de la idea: Elijan entre postres que ya tengan o preparen una porción pequeña para compartir, si ambos quieren.","Durante el momento, revisen si el ritmo y la propuesta siguen resultando cómodos para ambos.","Cierren con un gesto de agradecimiento o simplemente con una despedida amable, según lo que cada quien prefiera."]'::jsonb, '["¿Qué gesto sería bienvenido y cuál prefieres dejar opcional?","¿Qué te gustaría recordar de este rato, si te apetece compartirlo?","¿Prefieres elegir juntos cada detalle o dejar algunas cosas sencillas?","¿Qué plan pequeño te gustaría repetir a tu manera?","¿Qué detalle de este momento te resulta agradable?"]'::jsonb, 'Compartan fruta, té o una receta imaginaria.', '["Adapten iluminación, aroma, postura y volumen; eviten flores o fragancias que puedan causar molestias.","Cada quien decide qué probar y cuánto; comer no es un reto."]'::jsonb, '["Pregunten antes de contacto físico, fotografías o gestos sorpresa; todo puede ser opcional."]'::jsonb, 'Los detalles no llevan expectativas: acuerden cercanía, fotos y gestos; el plan puede terminar en una conversación tranquila.', true, 64),
  ('65-cena-tematica-en-casa', 'Cena temática en casa', 'romance-y-detalles', 'Elijan un tema amable y adapten la comida, música o mesa con lo que ya tengan. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Crear un momento afectuoso alrededor de crear una atmósfera sencilla con música y una idea común, sin suponer que alguien debe corresponder de cierta manera.', 90, 'media', 'interior', '["Elementos disponibles en casa","Comida ya elegida"]'::jsonb, 'Acuerden el tema entre ambos y mantengan las tareas decorativas opcionales.', '["Elijan juntos el ambiente y pregunten qué tipo de gesto, cercanía o recuerdo sería bienvenido hoy.","Preparen una versión sencilla de la idea: Elijan un tema amable y adapten la comida, música o mesa con lo que ya tengan.","Durante el momento, revisen si el ritmo y la propuesta siguen resultando cómodos para ambos.","Cierren con un gesto de agradecimiento o simplemente con una despedida amable, según lo que cada quien prefiera."]'::jsonb, '["¿Qué te gustaría recordar de este rato, si te apetece compartirlo?","¿Prefieres elegir juntos cada detalle o dejar algunas cosas sencillas?","¿Qué plan pequeño te gustaría repetir a tu manera?","¿Qué detalle de este momento te resulta agradable?","¿Qué ambiente te acomoda hoy: conversación, silencio o música?"]'::jsonb, 'Usen una canción o un color como tema de la cena.', '["Adapten iluminación, aroma, postura y volumen; eviten flores o fragancias que puedan causar molestias.","No se espera una producción perfecta ni que una sola persona organice todo."]'::jsonb, '["Pregunten antes de contacto físico, fotografías o gestos sorpresa; todo puede ser opcional."]'::jsonb, 'Los detalles no llevan expectativas: acuerden cercanía, fotos y gestos; el plan puede terminar en una conversación tranquila.', true, 65),
  ('66-recrear-una-primera-cita-a-nuestra-manera', 'Recrear una primera cita, a nuestra manera', 'romance-y-detalles', 'Elijan solo un detalle que ambos recuerden con gusto y conviértanlo en una nueva versión que represente cómo son ahora. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Crear un momento afectuoso alrededor de recordar un encuentro pasado y actualizarlo con preferencias actuales, sin suponer que alguien debe corresponder de cierta manera.', 90, 'baja', 'indistinto', '["Un detalle opcional relacionado con el recuerdo"]'::jsonb, 'Conversen primero sobre qué recuerdo sí quieren retomar y cuál prefieren dejar atrás.', '["Elijan juntos el ambiente y pregunten qué tipo de gesto, cercanía o recuerdo sería bienvenido hoy.","Preparen una versión sencilla de la idea: Elijan solo un detalle que ambos recuerden con gusto y conviértanlo en una nueva versión que represente cómo son ahora.","Durante el momento, revisen si el ritmo y la propuesta siguen resultando cómodos para ambos.","Cierren con un gesto de agradecimiento o simplemente con una despedida amable, según lo que cada quien prefiera."]'::jsonb, '["¿Prefieres elegir juntos cada detalle o dejar algunas cosas sencillas?","¿Qué plan pequeño te gustaría repetir a tu manera?","¿Qué detalle de este momento te resulta agradable?","¿Qué ambiente te acomoda hoy: conversación, silencio o música?","¿Qué gesto sería bienvenido y cuál prefieres dejar opcional?"]'::jsonb, 'Recreen solo una conversación o una bebida en casa.', '["Adapten iluminación, aroma, postura y volumen; eviten flores o fragancias que puedan causar molestias.","No asuman que la primera cita fue ideal; pueden cambiar cualquier elemento o no recrearla."]'::jsonb, '["Pregunten antes de contacto físico, fotografías o gestos sorpresa; todo puede ser opcional."]'::jsonb, 'Los detalles no llevan expectativas: acuerden cercanía, fotos y gestos; el plan puede terminar en una conversación tranquila.', true, 66),
  ('67-una-cita-de-sorpresas-pequenas', 'Una cita de sorpresas pequeñas', 'romance-y-detalles', 'Cada quien propone un detalle sencillo aprobado de antemano y lo revela en el momento que acuerden. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Crear un momento afectuoso alrededor de elegir detalles inesperados que ya caben dentro de límites acordados, sin suponer que alguien debe corresponder de cierta manera.', 60, 'baja', 'indistinto', '["Papelitos con ideas aprobadas"]'::jsonb, 'Definan juntos qué tipos de sorpresa son bienvenidos y cuáles no; pueden revelar todo desde el principio.', '["Elijan juntos el ambiente y pregunten qué tipo de gesto, cercanía o recuerdo sería bienvenido hoy.","Preparen una versión sencilla de la idea: Cada quien propone un detalle sencillo aprobado de antemano y lo revela en el momento que acuerden.","Durante el momento, revisen si el ritmo y la propuesta siguen resultando cómodos para ambos.","Cierren con un gesto de agradecimiento o simplemente con una despedida amable, según lo que cada quien prefiera."]'::jsonb, '["¿Qué plan pequeño te gustaría repetir a tu manera?","¿Qué detalle de este momento te resulta agradable?","¿Qué ambiente te acomoda hoy: conversación, silencio o música?","¿Qué gesto sería bienvenido y cuál prefieres dejar opcional?","¿Qué te gustaría recordar de este rato, si te apetece compartirlo?"]'::jsonb, 'Escojan entre dos canciones o preguntas escritas.', '["Adapten iluminación, aroma, postura y volumen; eviten flores o fragancias que puedan causar molestias.","Las sorpresas nunca implican contacto, regalos, exposición o planes no consentidos."]'::jsonb, '["Pregunten antes de contacto físico, fotografías o gestos sorpresa; todo puede ser opcional."]'::jsonb, 'Los detalles no llevan expectativas: acuerden cercanía, fotos y gestos; el plan puede terminar en una conversación tranquila.', true, 67),
  ('68-un-baile-lento', 'Un baile lento', 'romance-y-detalles', 'Elijan una canción y decidan si desean bailar juntos, moverse cada uno o escucharla sentados. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Crear un momento afectuoso alrededor de compartir música y movimiento con la distancia que ambos elijan, sin suponer que alguien debe corresponder de cierta manera.', 15, 'baja', 'interior', '["Una canción elegida por ambos","Espacio despejado"]'::jsonb, 'Pregunten qué distancia y movimientos se sienten bien antes de empezar.', '["Elijan juntos el ambiente y pregunten qué tipo de gesto, cercanía o recuerdo sería bienvenido hoy.","Preparen una versión sencilla de la idea: Elijan una canción y decidan si desean bailar juntos, moverse cada uno o escucharla sentados.","Durante el momento, revisen si el ritmo y la propuesta siguen resultando cómodos para ambos.","Cierren con un gesto de agradecimiento o simplemente con una despedida amable, según lo que cada quien prefiera."]'::jsonb, '["¿Qué detalle de este momento te resulta agradable?","¿Qué ambiente te acomoda hoy: conversación, silencio o música?","¿Qué gesto sería bienvenido y cuál prefieres dejar opcional?","¿Qué te gustaría recordar de este rato, si te apetece compartirlo?","¿Prefieres elegir juntos cada detalle o dejar algunas cosas sencillas?"]'::jsonb, 'Escuchen la canción y sigan el ritmo con las manos o los pies.', '["Adapten iluminación, aroma, postura y volumen; eviten flores o fragancias que puedan causar molestias.","El contacto físico siempre es opcional y puede detenerse en cualquier momento."]'::jsonb, '["Pregunten antes de contacto físico, fotografías o gestos sorpresa; todo puede ser opcional."]'::jsonb, 'Los detalles no llevan expectativas: acuerden cercanía, fotos y gestos; el plan puede terminar en una conversación tranquila.', true, 68),
  ('69-elegir-una-cancion-para-el-recuerdo', 'Elegir una canción para el recuerdo', 'romance-y-detalles', 'Escuchen algunas opciones y elijan una solo si encuentran una que les guste a ambos; también pueden guardar dos. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Crear un momento afectuoso alrededor de guardar una canción que represente el día para ambos, sin suponer que alguien debe corresponder de cierta manera.', 45, 'baja', 'indistinto', '["Acceso a música que ya utilicen"]'::jsonb, 'Acuerden si la canción quedará en una lista compartida o solo como idea escrita.', '["Elijan juntos el ambiente y pregunten qué tipo de gesto, cercanía o recuerdo sería bienvenido hoy.","Preparen una versión sencilla de la idea: Escuchen algunas opciones y elijan una solo si encuentran una que les guste a ambos; también pueden guardar dos.","Durante el momento, revisen si el ritmo y la propuesta siguen resultando cómodos para ambos.","Cierren con un gesto de agradecimiento o simplemente con una despedida amable, según lo que cada quien prefiera."]'::jsonb, '["¿Qué ambiente te acomoda hoy: conversación, silencio o música?","¿Qué gesto sería bienvenido y cuál prefieres dejar opcional?","¿Qué te gustaría recordar de este rato, si te apetece compartirlo?","¿Prefieres elegir juntos cada detalle o dejar algunas cosas sencillas?","¿Qué plan pequeño te gustaría repetir a tu manera?"]'::jsonb, 'Escriban el nombre de una canción sin reproducirla.', '["Adapten iluminación, aroma, postura y volumen; eviten flores o fragancias que puedan causar molestias.","No compartan listas o enlaces del otro fuera del espacio sin permiso."]'::jsonb, '["Pregunten antes de contacto físico, fotografías o gestos sorpresa; todo puede ser opcional."]'::jsonb, 'Los detalles no llevan expectativas: acuerden cercanía, fotos y gestos; el plan puede terminar en una conversación tranquila.', true, 69),
  ('70-una-tarde-sin-reloj', 'Una tarde sin reloj', 'romance-y-detalles', 'Elijan una actividad de baja preparación y déjenla terminar cuando el interés cambie, sin completar una lista. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Crear un momento afectuoso alrededor de disfrutar una actividad sencilla sin horarios rígidos, sin suponer que alguien debe corresponder de cierta manera.', 90, 'baja', 'indistinto', '["Lo que requiera la actividad elegida"]'::jsonb, 'Reserven un rato flexible y eviten fijar objetivos que conviertan el descanso en tarea.', '["Elijan juntos el ambiente y pregunten qué tipo de gesto, cercanía o recuerdo sería bienvenido hoy.","Preparen una versión sencilla de la idea: Elijan una actividad de baja preparación y déjenla terminar cuando el interés cambie, sin completar una lista.","Durante el momento, revisen si el ritmo y la propuesta siguen resultando cómodos para ambos.","Cierren con un gesto de agradecimiento o simplemente con una despedida amable, según lo que cada quien prefiera."]'::jsonb, '["¿Qué gesto sería bienvenido y cuál prefieres dejar opcional?","¿Qué te gustaría recordar de este rato, si te apetece compartirlo?","¿Prefieres elegir juntos cada detalle o dejar algunas cosas sencillas?","¿Qué plan pequeño te gustaría repetir a tu manera?","¿Qué detalle de este momento te resulta agradable?"]'::jsonb, 'Compartan quince minutos de música, lectura o charla.', '["Adapten iluminación, aroma, postura y volumen; eviten flores o fragancias que puedan causar molestias.","La flexibilidad también incluye pausar por necesidades prácticas."]'::jsonb, '["Pregunten antes de contacto físico, fotografías o gestos sorpresa; todo puede ser opcional."]'::jsonb, 'Los detalles no llevan expectativas: acuerden cercanía, fotos y gestos; el plan puede terminar en una conversación tranquila.', true, 70),
  ('71-ir-juntos-al-supermercado-y-cocinar', 'Ir juntos al supermercado y cocinar', 'vida-cotidiana', 'Hagan una lista corta de ingredientes que ambos quieran y después preparen una receta sencilla. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir una parte de la vida real alrededor de elegir ingredientes cotidianos y preparar una comida compartida, con libertad para simplificar o dejar algo para después.', 100, 'media', 'interior', '["Lista breve","Ingredientes elegidos","Utensilios habituales"]'::jsonb, 'Confirmen preferencias alimentarias y quién quiere hacer cada parte; la compra puede ser de artículos que ya tienen.', '["Elijan una versión manejable de la actividad y aclaren qué puede quedar pendiente.","Hagan juntos el primer paso: Hagan una lista corta de ingredientes que ambos quieran y después preparen una receta sencilla.","Repartan tareas o acompáñense como les resulte natural; pueden parar para descansar.","Cierren reconociendo lo que sí compartieron, sin convertirlo en una lista de pendientes."]'::jsonb, '["¿Qué parte de este plan disfrutas compartir y cuál prefieres hacer a tu manera?","¿Qué podríamos simplificar para que el plan sea amable?","¿Qué tarea cotidiana te resulta más agradable de lo que parece?","¿Qué haría este rato más cómodo en un día con poca energía?","¿Qué hábito pequeño te gustaría contarme?"]'::jsonb, 'Revisen la despensa y cocinen algo que ya esté disponible.', '["Ajusten tiempos, tareas, pausas y desplazamientos a la energía y necesidades prácticas de ambos.","Dividan traslado, carga y tareas según comodidad; no hace falta salir juntos para compartir el plan."]'::jsonb, '["Repartir una tarea no crea una obligación futura; acuerden cada actividad de nuevo cuando llegue el momento."]'::jsonb, 'El plan cotidiano no tiene que ser productivo: pueden simplificar, dividirse o dejar cosas sin terminar.', true, 71),
  ('72-un-domingo-tranquilo', 'Un domingo tranquilo', 'vida-cotidiana', 'Cada quien propone una actividad breve y un rato de descanso; decidan por separado qué quieren compartir. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir una parte de la vida real alrededor de elegir juntos una forma amable de pasar un día libre, con libertad para simplificar o dejar algo para después.', 120, 'baja', 'indistinto', '["Ninguno"]'::jsonb, 'Pregunten qué significa descanso para cada persona antes de llenar el día de planes.', '["Elijan una versión manejable de la actividad y aclaren qué puede quedar pendiente.","Hagan juntos el primer paso: Cada quien propone una actividad breve y un rato de descanso; decidan por separado qué quieren compartir.","Repartan tareas o acompáñense como les resulte natural; pueden parar para descansar.","Cierren reconociendo lo que sí compartieron, sin convertirlo en una lista de pendientes."]'::jsonb, '["¿Qué podríamos simplificar para que el plan sea amable?","¿Qué tarea cotidiana te resulta más agradable de lo que parece?","¿Qué haría este rato más cómodo en un día con poca energía?","¿Qué hábito pequeño te gustaría contarme?","¿Qué parte repetirías tal cual y qué dejarías opcional?"]'::jsonb, 'Compartan una bebida y una pausa sin agenda.', '["Ajusten tiempos, tareas, pausas y desplazamientos a la energía y necesidades prácticas de ambos.","No asuman que descanso significa lo mismo para ambos; el tiempo individual también cabe."]'::jsonb, '["Repartir una tarea no crea una obligación futura; acuerden cada actividad de nuevo cuando llegue el momento."]'::jsonb, 'El plan cotidiano no tiene que ser productivo: pueden simplificar, dividirse o dejar cosas sin terminar.', true, 72),
  ('73-paseo-con-mascotas', 'Paseo con mascotas', 'vida-cotidiana', 'Si ambos están de acuerdo y la mascota está cómoda, hagan un paseo corto siguiendo sus señales y rutinas. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir una parte de la vida real alrededor de salir con animales de compañía respetando sus necesidades, con libertad para simplificar o dejar algo para después.', 45, 'media', 'exterior', '["Correa y elementos habituales de la mascota","Agua"]'::jsonb, 'Asegúrense de que la mascota y ambas personas disfruten la compañía; elijan una ruta segura.', '["Elijan una versión manejable de la actividad y aclaren qué puede quedar pendiente.","Hagan juntos el primer paso: Si ambos están de acuerdo y la mascota está cómoda, hagan un paseo corto siguiendo sus señales y rutinas.","Repartan tareas o acompáñense como les resulte natural; pueden parar para descansar.","Cierren reconociendo lo que sí compartieron, sin convertirlo en una lista de pendientes."]'::jsonb, '["¿Qué tarea cotidiana te resulta más agradable de lo que parece?","¿Qué haría este rato más cómodo en un día con poca energía?","¿Qué hábito pequeño te gustaría contarme?","¿Qué parte repetirías tal cual y qué dejarías opcional?","¿Qué parte de este plan disfrutas compartir y cuál prefieres hacer a tu manera?"]'::jsonb, 'Compartan fotos propias o jueguen con la mascota en casa si es apropiado.', '["Ajusten tiempos, tareas, pausas y desplazamientos a la energía y necesidades prácticas de ambos.","Prioricen bienestar animal, clima, accesibilidad y distancia; no fuercen la interacción."]'::jsonb, '["Repartir una tarea no crea una obligación futura; acuerden cada actividad de nuevo cuando llegue el momento."]'::jsonb, 'El plan cotidiano no tiene que ser productivo: pueden simplificar, dividirse o dejar cosas sin terminar.', true, 73),
  ('74-visitar-un-mercado-local', 'Visitar un mercado local', 'vida-cotidiana', 'Recorran pasillos que les interesen y elijan algo para mirar, aprender o probar solo si ambos quieren. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir una parte de la vida real alrededor de observar productos, colores y costumbres de un mercado, con libertad para simplificar o dejar algo para después.', 75, 'media', 'exterior', '["Bolsa reutilizable opcional","Agua"]'::jsonb, 'Confirmen que el mercado esté abierto y cómo acceder; no es necesario comprar.', '["Elijan una versión manejable de la actividad y aclaren qué puede quedar pendiente.","Hagan juntos el primer paso: Recorran pasillos que les interesen y elijan algo para mirar, aprender o probar solo si ambos quieren.","Repartan tareas o acompáñense como les resulte natural; pueden parar para descansar.","Cierren reconociendo lo que sí compartieron, sin convertirlo en una lista de pendientes."]'::jsonb, '["¿Qué haría este rato más cómodo en un día con poca energía?","¿Qué hábito pequeño te gustaría contarme?","¿Qué parte repetirías tal cual y qué dejarías opcional?","¿Qué parte de este plan disfrutas compartir y cuál prefieres hacer a tu manera?","¿Qué podríamos simplificar para que el plan sea amable?"]'::jsonb, 'Miren un recetario o productos que ya tengan en casa y cuenten qué conocen.', '["Ajusten tiempos, tareas, pausas y desplazamientos a la energía y necesidades prácticas de ambos.","Consideren ruido, aglomeración y movilidad; elijan una visita breve o una alternativa tranquila."]'::jsonb, '["Repartir una tarea no crea una obligación futura; acuerden cada actividad de nuevo cuando llegue el momento."]'::jsonb, 'El plan cotidiano no tiene que ser productivo: pueden simplificar, dividirse o dejar cosas sin terminar.', true, 74),
  ('75-un-dia-de-mandados-sin-prisas', 'Un día de mandados sin prisas', 'vida-cotidiana', 'Elijan un mandado breve que ambos quieran compartir y acuerden si la otra persona acompaña, espera o prefiere otra cosa. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir una parte de la vida real alrededor de acompañarse en una tarea práctica con flexibilidad, con libertad para simplificar o dejar algo para después.', 60, 'baja', 'exterior', '["Lista de pendientes solo si hace falta"]'::jsonb, 'Confirmen que el mandado tenga sentido para ambos y que no interfiera con otras obligaciones.', '["Elijan una versión manejable de la actividad y aclaren qué puede quedar pendiente.","Hagan juntos el primer paso: Elijan un mandado breve que ambos quieran compartir y acuerden si la otra persona acompaña, espera o prefiere otra cosa.","Repartan tareas o acompáñense como les resulte natural; pueden parar para descansar.","Cierren reconociendo lo que sí compartieron, sin convertirlo en una lista de pendientes."]'::jsonb, '["¿Qué hábito pequeño te gustaría contarme?","¿Qué parte repetirías tal cual y qué dejarías opcional?","¿Qué parte de este plan disfrutas compartir y cuál prefieres hacer a tu manera?","¿Qué podríamos simplificar para que el plan sea amable?","¿Qué tarea cotidiana te resulta más agradable de lo que parece?"]'::jsonb, 'Resuelvan juntos un pendiente sencillo en casa o conversen mientras uno organiza.', '["Ajusten tiempos, tareas, pausas y desplazamientos a la energía y necesidades prácticas de ambos.","Los pendientes personales pueden mantenerse privados; nadie tiene que explicar trámites."]'::jsonb, '["Repartir una tarea no crea una obligación futura; acuerden cada actividad de nuevo cuando llegue el momento."]'::jsonb, 'El plan cotidiano no tiene que ser productivo: pueden simplificar, dividirse o dejar cosas sin terminar.', true, 75),
  ('76-preparar-desayuno-juntos', 'Preparar desayuno juntos', 'vida-cotidiana', 'Elijan una preparación fácil y turnen tareas; pueden desayunar a la hora que les funcione. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir una parte de la vida real alrededor de repartirse una comida sencilla al comenzar el día, con libertad para simplificar o dejar algo para después.', 45, 'baja', 'interior', '["Alimentos elegidos por ambos","Utensilios habituales"]'::jsonb, 'Revisen ingredientes y acuerden una opción que ambos disfruten.', '["Elijan una versión manejable de la actividad y aclaren qué puede quedar pendiente.","Hagan juntos el primer paso: Elijan una preparación fácil y turnen tareas; pueden desayunar a la hora que les funcione.","Repartan tareas o acompáñense como les resulte natural; pueden parar para descansar.","Cierren reconociendo lo que sí compartieron, sin convertirlo en una lista de pendientes."]'::jsonb, '["¿Qué parte repetirías tal cual y qué dejarías opcional?","¿Qué parte de este plan disfrutas compartir y cuál prefieres hacer a tu manera?","¿Qué podríamos simplificar para que el plan sea amable?","¿Qué tarea cotidiana te resulta más agradable de lo que parece?","¿Qué haría este rato más cómodo en un día con poca energía?"]'::jsonb, 'Compartan fruta, cereal o una bebida lista.', '["Ajusten tiempos, tareas, pausas y desplazamientos a la energía y necesidades prácticas de ambos.","El desayuno no tiene que ser temprano ni cocinarse desde cero."]'::jsonb, '["Repartir una tarea no crea una obligación futura; acuerden cada actividad de nuevo cuando llegue el momento."]'::jsonb, 'El plan cotidiano no tiene que ser productivo: pueden simplificar, dividirse o dejar cosas sin terminar.', true, 76),
  ('77-una-caminata-matutina', 'Una caminata matutina', 'vida-cotidiana', 'Elijan un tramo corto y seguro, a un paso conversable; vuelvan cuando el cuerpo o el tiempo lo pidan. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir una parte de la vida real alrededor de compartir movimiento suave al inicio del día, con libertad para simplificar o dejar algo para después.', 30, 'baja', 'exterior', '["Calzado cómodo","Agua opcional"]'::jsonb, 'Confirmen clima, ruta y accesibilidad; pueden salir más tarde.', '["Elijan una versión manejable de la actividad y aclaren qué puede quedar pendiente.","Hagan juntos el primer paso: Elijan un tramo corto y seguro, a un paso conversable; vuelvan cuando el cuerpo o el tiempo lo pidan.","Repartan tareas o acompáñense como les resulte natural; pueden parar para descansar.","Cierren reconociendo lo que sí compartieron, sin convertirlo en una lista de pendientes."]'::jsonb, '["¿Qué parte de este plan disfrutas compartir y cuál prefieres hacer a tu manera?","¿Qué podríamos simplificar para que el plan sea amable?","¿Qué tarea cotidiana te resulta más agradable de lo que parece?","¿Qué haría este rato más cómodo en un día con poca energía?","¿Qué hábito pequeño te gustaría contarme?"]'::jsonb, 'Hagan una caminata por casa o estiren junto a una ventana.', '["Ajusten tiempos, tareas, pausas y desplazamientos a la energía y necesidades prácticas de ambos.","No conviertan el ritmo o distancia en logro; cualquier desplazamiento cómodo cuenta."]'::jsonb, '["Repartir una tarea no crea una obligación futura; acuerden cada actividad de nuevo cuando llegue el momento."]'::jsonb, 'El plan cotidiano no tiene que ser productivo: pueden simplificar, dividirse o dejar cosas sin terminar.', true, 77),
  ('78-conocer-un-hobby-del-otro', 'Conocer un hobby del otro', 'vida-cotidiana', 'Una persona elige qué mostrar y cuánto explicar; la otra puede observar, probar o hacer preguntas. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir una parte de la vida real alrededor de observar o probar una afición con guía de quien la disfruta, con libertad para simplificar o dejar algo para después.', 60, 'baja', 'indistinto', '["Materiales propios del hobby, opcionales"]'::jsonb, 'Pregunten qué parte de la afición es fácil compartir y preparen una versión inicial.', '["Elijan una versión manejable de la actividad y aclaren qué puede quedar pendiente.","Hagan juntos el primer paso: Una persona elige qué mostrar y cuánto explicar; la otra puede observar, probar o hacer preguntas.","Repartan tareas o acompáñense como les resulte natural; pueden parar para descansar.","Cierren reconociendo lo que sí compartieron, sin convertirlo en una lista de pendientes."]'::jsonb, '["¿Qué podríamos simplificar para que el plan sea amable?","¿Qué tarea cotidiana te resulta más agradable de lo que parece?","¿Qué haría este rato más cómodo en un día con poca energía?","¿Qué hábito pequeño te gustaría contarme?","¿Qué parte repetirías tal cual y qué dejarías opcional?"]'::jsonb, 'Miren una demostración breve o conversen sobre cómo empezó el hobby.', '["Ajusten tiempos, tareas, pausas y desplazamientos a la energía y necesidades prácticas de ambos.","No es una clase ni se necesita volverse experto; respeten objetos y materiales personales."]'::jsonb, '["Repartir una tarea no crea una obligación futura; acuerden cada actividad de nuevo cuando llegue el momento."]'::jsonb, 'El plan cotidiano no tiene que ser productivo: pueden simplificar, dividirse o dejar cosas sin terminar.', true, 78),
  ('79-un-plan-con-amigos-si-ambos-quieren', 'Un plan con amigos, si ambos quieren', 'vida-cotidiana', 'Propongan una actividad simple con amistades solo si ambos desean; acuerden cuánto quieren participar y cómo retirarse. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir una parte de la vida real alrededor de compartir una actividad grupal manteniendo libertad individual, con libertad para simplificar o dejar algo para después.', 120, 'media', 'indistinto', '["Ninguno; depende de la actividad acordada"]'::jsonb, 'Consulten a las amistades antes de incluirlas y confirmen que el plan les acomoda a todos.', '["Elijan una versión manejable de la actividad y aclaren qué puede quedar pendiente.","Hagan juntos el primer paso: Propongan una actividad simple con amistades solo si ambos desean; acuerden cuánto quieren participar y cómo retirarse.","Repartan tareas o acompáñense como les resulte natural; pueden parar para descansar.","Cierren reconociendo lo que sí compartieron, sin convertirlo en una lista de pendientes."]'::jsonb, '["¿Qué tarea cotidiana te resulta más agradable de lo que parece?","¿Qué haría este rato más cómodo en un día con poca energía?","¿Qué hábito pequeño te gustaría contarme?","¿Qué parte repetirías tal cual y qué dejarías opcional?","¿Qué parte de este plan disfrutas compartir y cuál prefieres hacer a tu manera?"]'::jsonb, 'Hagan una actividad cooperativa solo entre ustedes o dejen el plan para otra ocasión.', '["Ajusten tiempos, tareas, pausas y desplazamientos a la energía y necesidades prácticas de ambos.","La invitación es opcional; nadie tiene que presentar el vínculo ni compartir información personal."]'::jsonb, '["Repartir una tarea no crea una obligación futura; acuerden cada actividad de nuevo cuando llegue el momento."]'::jsonb, 'El plan cotidiano no tiene que ser productivo: pueden simplificar, dividirse o dejar cosas sin terminar.', true, 79),
  ('80-una-reunion-familiar-consensuada', 'Una reunión familiar consensuada', 'vida-cotidiana', 'Conversen si ambos desean una reunión, qué límites cuidarían y qué alternativa prefieren si alguien no quiere asistir. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir una parte de la vida real alrededor de hablar antes de compartir tiempo con familiares, con libertad para simplificar o dejar algo para después.', 90, 'baja', 'indistinto', '["Ninguno"]'::jsonb, 'No inviten ni contacten familiares sin consultar; acuerden expectativas y una forma cómoda de retirarse.', '["Elijan una versión manejable de la actividad y aclaren qué puede quedar pendiente.","Hagan juntos el primer paso: Conversen si ambos desean una reunión, qué límites cuidarían y qué alternativa prefieren si alguien no quiere asistir.","Repartan tareas o acompáñense como les resulte natural; pueden parar para descansar.","Cierren reconociendo lo que sí compartieron, sin convertirlo en una lista de pendientes."]'::jsonb, '["¿Qué haría este rato más cómodo en un día con poca energía?","¿Qué hábito pequeño te gustaría contarme?","¿Qué parte repetirías tal cual y qué dejarías opcional?","¿Qué parte de este plan disfrutas compartir y cuál prefieres hacer a tu manera?","¿Qué podríamos simplificar para que el plan sea amable?"]'::jsonb, 'Conversen sobre qué haría una reunión futura más amable, sin fijar fecha.', '["Ajusten tiempos, tareas, pausas y desplazamientos a la energía y necesidades prácticas de ambos.","La decisión puede ser no ir; respeten privacidad y no exijan explicaciones familiares."]'::jsonb, '["Repartir una tarea no crea una obligación futura; acuerden cada actividad de nuevo cuando llegue el momento."]'::jsonb, 'El plan cotidiano no tiene que ser productivo: pueden simplificar, dividirse o dejar cosas sin terminar.', true, 80),
  ('81-una-actividad-de-voluntariado', 'Una actividad de voluntariado', 'vida-cotidiana', 'Busquen información directamente de organizaciones verificables y elijan una actividad solo si condiciones y propósito les convencen. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir una parte de la vida real alrededor de explorar una forma de contribuir que ambos consideren significativa, con libertad para simplificar o dejar algo para después.', 120, 'media', 'indistinto', '["Los que la organización indique"]'::jsonb, 'Confirmen requisitos, accesibilidad y tareas con la organización; no se da por hecho que haya cupo.', '["Elijan una versión manejable de la actividad y aclaren qué puede quedar pendiente.","Hagan juntos el primer paso: Busquen información directamente de organizaciones verificables y elijan una actividad solo si condiciones y propósito les convencen.","Repartan tareas o acompáñense como les resulte natural; pueden parar para descansar.","Cierren reconociendo lo que sí compartieron, sin convertirlo en una lista de pendientes."]'::jsonb, '["¿Qué hábito pequeño te gustaría contarme?","¿Qué parte repetirías tal cual y qué dejarías opcional?","¿Qué parte de este plan disfrutas compartir y cuál prefieres hacer a tu manera?","¿Qué podríamos simplificar para que el plan sea amable?","¿Qué tarea cotidiana te resulta más agradable de lo que parece?"]'::jsonb, 'Hablen de causas que les interesan o realicen una ayuda pequeña que ya esté a su alcance.', '["Ajusten tiempos, tareas, pausas y desplazamientos a la energía y necesidades prácticas de ambos.","Respeten a las comunidades beneficiarias; no tomen ni compartan fotos sin permiso."]'::jsonb, '["Repartir una tarea no crea una obligación futura; acuerden cada actividad de nuevo cuando llegue el momento."]'::jsonb, 'El plan cotidiano no tiene que ser productivo: pueden simplificar, dividirse o dejar cosas sin terminar.', true, 81),
  ('82-planear-una-escapada-juntos', 'Planear una escapada juntos', 'vida-cotidiana', 'Cada quien propone qué le gustaría sentir o hacer; esbocen dos opciones sin reservar ni comprometerse hoy. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir una parte de la vida real alrededor de imaginar una salida breve teniendo en cuenta preferencias y accesibilidad, con libertad para simplificar o dejar algo para después.', 60, 'baja', 'indistinto', '["Papel o notas personales opcionales"]'::jsonb, 'Anoten duración, movilidad, descanso y preferencias; mantengan lugares y fechas por verificar.', '["Elijan una versión manejable de la actividad y aclaren qué puede quedar pendiente.","Hagan juntos el primer paso: Cada quien propone qué le gustaría sentir o hacer; esbocen dos opciones sin reservar ni comprometerse hoy.","Repartan tareas o acompáñense como les resulte natural; pueden parar para descansar.","Cierren reconociendo lo que sí compartieron, sin convertirlo en una lista de pendientes."]'::jsonb, '["¿Qué parte repetirías tal cual y qué dejarías opcional?","¿Qué parte de este plan disfrutas compartir y cuál prefieres hacer a tu manera?","¿Qué podríamos simplificar para que el plan sea amable?","¿Qué tarea cotidiana te resulta más agradable de lo que parece?","¿Qué haría este rato más cómodo en un día con poca energía?"]'::jsonb, 'Diseñen un itinerario imaginario para un día libre cerca de casa.', '["Ajusten tiempos, tareas, pausas y desplazamientos a la energía y necesidades prácticas de ambos.","No fijen fechas ni compromisos de viaje; pueden dejarlo como una idea."]'::jsonb, '["Repartir una tarea no crea una obligación futura; acuerden cada actividad de nuevo cuando llegue el momento."]'::jsonb, 'El plan cotidiano no tiene que ser productivo: pueden simplificar, dividirse o dejar cosas sin terminar.', true, 82),
  ('83-una-tarde-de-juegos-en-casa', 'Una tarde de juegos en casa', 'vida-cotidiana', 'Preparen dos opciones y alternen quién elige; pueden inventar reglas o terminar una ronda antes de acabar. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir una parte de la vida real alrededor de elegir juegos sencillos y cambiar de actividad cuando quieran, con libertad para simplificar o dejar algo para después.', 75, 'baja', 'interior', '["Juegos o materiales que ya tengan"]'::jsonb, 'Dejen a mano los juegos y acuerden que nadie debe terminar una partida.', '["Elijan una versión manejable de la actividad y aclaren qué puede quedar pendiente.","Hagan juntos el primer paso: Preparen dos opciones y alternen quién elige; pueden inventar reglas o terminar una ronda antes de acabar.","Repartan tareas o acompáñense como les resulte natural; pueden parar para descansar.","Cierren reconociendo lo que sí compartieron, sin convertirlo en una lista de pendientes."]'::jsonb, '["¿Qué parte de este plan disfrutas compartir y cuál prefieres hacer a tu manera?","¿Qué podríamos simplificar para que el plan sea amable?","¿Qué tarea cotidiana te resulta más agradable de lo que parece?","¿Qué haría este rato más cómodo en un día con poca energía?","¿Qué hábito pequeño te gustaría contarme?"]'::jsonb, 'Jueguen a palabras, dibujo o preguntas sin materiales.', '["Ajusten tiempos, tareas, pausas y desplazamientos a la energía y necesidades prácticas de ambos.","Elijan actividades accesibles y de baja presión; una persona puede observar o proponer otra."]'::jsonb, '["Repartir una tarea no crea una obligación futura; acuerden cada actividad de nuevo cuando llegue el momento."]'::jsonb, 'El plan cotidiano no tiene que ser productivo: pueden simplificar, dividirse o dejar cosas sin terminar.', true, 83),
  ('84-organizar-un-pequeno-espacio-creativo', 'Organizar un pequeño espacio creativo', 'vida-cotidiana', 'Elijan una superficie pequeña, agrupen materiales y acomoden solo lo que les gustaría usar en el futuro. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir una parte de la vida real alrededor de ordenar un rincón que invite a una actividad que ambos disfruten, con libertad para simplificar o dejar algo para después.', 60, 'baja', 'interior', '["Caja o superficie disponible","Materiales que quieran conservar"]'::jsonb, 'Acuerden qué objetos se pueden mover y qué pertenece a cada quien.', '["Elijan una versión manejable de la actividad y aclaren qué puede quedar pendiente.","Hagan juntos el primer paso: Elijan una superficie pequeña, agrupen materiales y acomoden solo lo que les gustaría usar en el futuro.","Repartan tareas o acompáñense como les resulte natural; pueden parar para descansar.","Cierren reconociendo lo que sí compartieron, sin convertirlo en una lista de pendientes."]'::jsonb, '["¿Qué podríamos simplificar para que el plan sea amable?","¿Qué tarea cotidiana te resulta más agradable de lo que parece?","¿Qué haría este rato más cómodo en un día con poca energía?","¿Qué hábito pequeño te gustaría contarme?","¿Qué parte repetirías tal cual y qué dejarías opcional?"]'::jsonb, 'Dibujen cómo podría quedar el espacio sin mover nada.', '["Ajusten tiempos, tareas, pausas y desplazamientos a la energía y necesidades prácticas de ambos.","No desechen ni reorganizen objetos ajenos sin permiso; pueden detenerse tras una sola superficie."]'::jsonb, '["Repartir una tarea no crea una obligación futura; acuerden cada actividad de nuevo cuando llegue el momento."]'::jsonb, 'El plan cotidiano no tiene que ser productivo: pueden simplificar, dividirse o dejar cosas sin terminar.', true, 84),
  ('85-un-dia-sencillo-sin-actividades-especiales', 'Un día sencillo sin actividades especiales', 'vida-cotidiana', 'Elijan una comida, una pausa o una conversación espontánea y dejen que el resto del día siga como venga. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Compartir una parte de la vida real alrededor de compartir presencia sin tener que producir un recuerdo o cumplir un plan, con libertad para simplificar o dejar algo para después.', 60, 'baja', 'indistinto', '["Ninguno"]'::jsonb, 'Acuerden que no hace falta llenar el tiempo ni documentarlo.', '["Elijan una versión manejable de la actividad y aclaren qué puede quedar pendiente.","Hagan juntos el primer paso: Elijan una comida, una pausa o una conversación espontánea y dejen que el resto del día siga como venga.","Repartan tareas o acompáñense como les resulte natural; pueden parar para descansar.","Cierren reconociendo lo que sí compartieron, sin convertirlo en una lista de pendientes."]'::jsonb, '["¿Qué tarea cotidiana te resulta más agradable de lo que parece?","¿Qué haría este rato más cómodo en un día con poca energía?","¿Qué hábito pequeño te gustaría contarme?","¿Qué parte repetirías tal cual y qué dejarías opcional?","¿Qué parte de este plan disfrutas compartir y cuál prefieres hacer a tu manera?"]'::jsonb, 'Salúdense, compartan unos minutos y luego continúen con sus actividades.', '["Ajusten tiempos, tareas, pausas y desplazamientos a la energía y necesidades prácticas de ambos.","El tiempo individual y cambiar de idea siguen siendo bienvenidos."]'::jsonb, '["Repartir una tarea no crea una obligación futura; acuerden cada actividad de nuevo cuando llegue el momento."]'::jsonb, 'El plan cotidiano no tiene que ser productivo: pueden simplificar, dividirse o dejar cosas sin terminar.', true, 85),
  ('86-que-significa-amar-para-nosotros', 'Qué significa amar para nosotros', 'conversaciones-importantes', 'Cada quien puede compartir una palabra, gesto cotidiano o valor que asocia con amar, sin asumir una definición única. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Escucharse acerca de las formas personales de entender el amor y el cuidado con cuidado y claridad, sin evaluar compatibilidad ni forzar acuerdos.', 60, 'baja', 'indistinto', '[]'::jsonb, 'Elijan una pregunta y acuerden que respuestas distintas pueden convivir.', '["Antes de empezar, acuerden que cualquier persona puede pausar, pasar una pregunta o terminar la conversación.","Elijan una sola puerta de entrada: Cada quien puede compartir una palabra, gesto cotidiano o valor que asocia con amar, sin asumir una definición única.","Escuchen para entender; pregunten antes de aconsejar, debatir o intentar resolver.","Cierren sin exigir una conclusión. Si algo requiere seguimiento, cada quien decide si desea retomarlo otro día."]'::jsonb, '["¿Qué significa para ti las formas personales de entender el amor y el cuidado en situaciones cotidianas?","¿Qué necesitarías para conversar de esto con calma?","¿Hay una parte que prefieres dejar abierta o pensar después?","¿Qué podrías pedir o proponer sin esperar que haya una sola respuesta?","¿Qué te ayudaría a cerrar el tema por hoy con tranquilidad?"]'::jsonb, 'Compartan un gesto de cuidado que valoran, sin definir toda la relación.', '["Pueden conversar por escrito, en varios momentos o con descansos; elijan un nivel de detalle que se sienta seguro.","No hace falta llegar a una definición común ni revelar experiencias privadas."]'::jsonb, '["La pausa está disponible en todo momento. No presionen para revelar, decidir, perdonar ni definir el vínculo."]'::jsonb, 'Elijan una sola pregunta. No es una prueba ni una sesión terapéutica; pausar o no coincidir no exige una solución inmediata.', true, 86),
  ('87-que-necesitamos-para-sentirnos-seguros', 'Qué necesitamos para sentirnos seguros', 'conversaciones-importantes', 'Hablen de acciones concretas que ayudan a sentirse tranquilos y de cómo pedir una pausa cuando algo no se siente bien. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Escucharse acerca de las conductas que dan confianza y comodidad en un vínculo con cuidado y claridad, sin evaluar compatibilidad ni forzar acuerdos.', 60, 'baja', 'indistinto', '[]'::jsonb, 'Definan un marco de escucha y conversen solo de lo que cada quien elija compartir.', '["Antes de empezar, acuerden que cualquier persona puede pausar, pasar una pregunta o terminar la conversación.","Elijan una sola puerta de entrada: Hablen de acciones concretas que ayudan a sentirse tranquilos y de cómo pedir una pausa cuando algo no se siente bien.","Escuchen para entender; pregunten antes de aconsejar, debatir o intentar resolver.","Cierren sin exigir una conclusión. Si algo requiere seguimiento, cada quien decide si desea retomarlo otro día."]'::jsonb, '["¿Qué necesitarías para conversar de esto con calma?","¿Hay una parte que prefieres dejar abierta o pensar después?","¿Qué podrías pedir o proponer sin esperar que haya una sola respuesta?","¿Qué te ayudaría a cerrar el tema por hoy con tranquilidad?","¿Qué límite o pausa quieres que respetemos durante esta charla?"]'::jsonb, 'Mencionen una condición práctica que vuelve cómoda una conversación.', '["Pueden conversar por escrito, en varios momentos o con descansos; elijan un nivel de detalle que se sienta seguro.","No pidan detalles de experiencias difíciles; cada quien controla lo que cuenta."]'::jsonb, '["La pausa está disponible en todo momento. No presionen para revelar, decidir, perdonar ni definir el vínculo."]'::jsonb, 'Elijan una sola pregunta. No es una prueba ni una sesión terapéutica; pausar o no coincidir no exige una solución inmediata.', true, 87),
  ('88-limites-que-queremos-respetar', 'Límites que queremos respetar', 'conversaciones-importantes', 'Cada quien puede nombrar un límite concreto y una frase respetuosa para comunicarlo; no necesitan negociarlo en el momento. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Escucharse acerca de límites cotidianos y maneras de expresarlos con cuidado y claridad, sin evaluar compatibilidad ni forzar acuerdos.', 60, 'baja', 'indistinto', '[]'::jsonb, 'Acuerden que escuchar un límite no obliga a debatirlo ni a justificarlo.', '["Antes de empezar, acuerden que cualquier persona puede pausar, pasar una pregunta o terminar la conversación.","Elijan una sola puerta de entrada: Cada quien puede nombrar un límite concreto y una frase respetuosa para comunicarlo; no necesitan negociarlo en el momento.","Escuchen para entender; pregunten antes de aconsejar, debatir o intentar resolver.","Cierren sin exigir una conclusión. Si algo requiere seguimiento, cada quien decide si desea retomarlo otro día."]'::jsonb, '["¿Hay una parte que prefieres dejar abierta o pensar después?","¿Qué podrías pedir o proponer sin esperar que haya una sola respuesta?","¿Qué te ayudaría a cerrar el tema por hoy con tranquilidad?","¿Qué límite o pausa quieres que respetemos durante esta charla?","¿Quieres que te escuche, te pregunte o pensemos opciones juntos?"]'::jsonb, 'Elijan un ejemplo neutral como privacidad, tiempo personal o fotografías.', '["Pueden conversar por escrito, en varios momentos o con descansos; elijan un nivel de detalle que se sienta seguro.","Un límite se puede reafirmar o cambiar; ninguna persona debe ser presionada para aceptar contacto."]'::jsonb, '["La pausa está disponible en todo momento. No presionen para revelar, decidir, perdonar ni definir el vínculo."]'::jsonb, 'Elijan una sola pregunta. No es una prueba ni una sesión terapéutica; pausar o no coincidir no exige una solución inmediata.', true, 88),
  ('89-como-preferimos-resolver-desacuerdos', 'Cómo preferimos resolver desacuerdos', 'conversaciones-importantes', 'Describan qué ayuda a conversar cuando no coinciden y acuerden una señal para tomar distancia antes de responder. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Escucharse acerca de formas de pausar y retomar una diferencia con respeto con cuidado y claridad, sin evaluar compatibilidad ni forzar acuerdos.', 60, 'baja', 'indistinto', '[]'::jsonb, 'Eviten comenzar con un desacuerdo activo; elijan un ejemplo cotidiano y de baja intensidad.', '["Antes de empezar, acuerden que cualquier persona puede pausar, pasar una pregunta o terminar la conversación.","Elijan una sola puerta de entrada: Describan qué ayuda a conversar cuando no coinciden y acuerden una señal para tomar distancia antes de responder.","Escuchen para entender; pregunten antes de aconsejar, debatir o intentar resolver.","Cierren sin exigir una conclusión. Si algo requiere seguimiento, cada quien decide si desea retomarlo otro día."]'::jsonb, '["¿Qué podrías pedir o proponer sin esperar que haya una sola respuesta?","¿Qué te ayudaría a cerrar el tema por hoy con tranquilidad?","¿Qué límite o pausa quieres que respetemos durante esta charla?","¿Quieres que te escuche, te pregunte o pensemos opciones juntos?","¿Qué significa para ti formas de pausar y retomar una diferencia con respeto en situaciones cotidianas?"]'::jsonb, 'Compartan qué les sirve para calmarse después de un día difícil, sin discutir un conflicto concreto.', '["Pueden conversar por escrito, en varios momentos o con descansos; elijan un nivel de detalle que se sienta seguro.","No usen la charla para ganar un argumento ni para reabrir un tema doloroso sin acuerdo."]'::jsonb, '["La pausa está disponible en todo momento. No presionen para revelar, decidir, perdonar ni definir el vínculo."]'::jsonb, 'Elijan una sola pregunta. No es una prueba ni una sesión terapéutica; pausar o no coincidir no exige una solución inmediata.', true, 89),
  ('90-nuestras-metas-personales', 'Nuestras metas personales', 'conversaciones-importantes', 'Cada persona comparte una meta propia y el tipo de apoyo que agradecería, incluso si ese apoyo es dar espacio. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Escucharse acerca de sueños individuales que cada quien quiere seguir cuidando con cuidado y claridad, sin evaluar compatibilidad ni forzar acuerdos.', 60, 'baja', 'indistinto', '[]'::jsonb, 'Decidan si hablarán de metas cercanas o futuras y mantengan abierto el derecho a no responder.', '["Antes de empezar, acuerden que cualquier persona puede pausar, pasar una pregunta o terminar la conversación.","Elijan una sola puerta de entrada: Cada persona comparte una meta propia y el tipo de apoyo que agradecería, incluso si ese apoyo es dar espacio.","Escuchen para entender; pregunten antes de aconsejar, debatir o intentar resolver.","Cierren sin exigir una conclusión. Si algo requiere seguimiento, cada quien decide si desea retomarlo otro día."]'::jsonb, '["¿Qué te ayudaría a cerrar el tema por hoy con tranquilidad?","¿Qué límite o pausa quieres que respetemos durante esta charla?","¿Quieres que te escuche, te pregunte o pensemos opciones juntos?","¿Qué significa para ti sueños individuales que cada quien quiere seguir cuidando en situaciones cotidianas?","¿Qué necesitarías para conversar de esto con calma?"]'::jsonb, 'Compartan una curiosidad o aprendizaje que les gustaría explorar.', '["Pueden conversar por escrito, en varios momentos o con descansos; elijan un nivel de detalle que se sienta seguro.","Las metas no tienen que coincidir; apoyar también puede significar respetar independencia."]'::jsonb, '["La pausa está disponible en todo momento. No presionen para revelar, decidir, perdonar ni definir el vínculo."]'::jsonb, 'Elijan una sola pregunta. No es una prueba ni una sesión terapéutica; pausar o no coincidir no exige una solución inmediata.', true, 90),
  ('91-como-nos-gusta-recibir-carino', 'Cómo nos gusta recibir cariño', 'conversaciones-importantes', 'Compartan uno o dos gestos que se sienten agradables y recuerden preguntar antes de asumir que el otro los quiere. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Escucharse acerca de gestos de afecto preferidos y formas de pedirlos con cuidado y claridad, sin evaluar compatibilidad ni forzar acuerdos.', 45, 'baja', 'indistinto', '[]'::jsonb, 'Acuerden ejemplos que no impliquen contacto físico, para que la charla sea accesible a ambos.', '["Antes de empezar, acuerden que cualquier persona puede pausar, pasar una pregunta o terminar la conversación.","Elijan una sola puerta de entrada: Compartan uno o dos gestos que se sienten agradables y recuerden preguntar antes de asumir que el otro los quiere.","Escuchen para entender; pregunten antes de aconsejar, debatir o intentar resolver.","Cierren sin exigir una conclusión. Si algo requiere seguimiento, cada quien decide si desea retomarlo otro día."]'::jsonb, '["¿Qué límite o pausa quieres que respetemos durante esta charla?","¿Quieres que te escuche, te pregunte o pensemos opciones juntos?","¿Qué significa para ti gestos de afecto preferidos y formas de pedirlos en situaciones cotidianas?","¿Qué necesitarías para conversar de esto con calma?","¿Hay una parte que prefieres dejar abierta o pensar después?"]'::jsonb, 'Hablen de un mensaje, palabra o detalle cotidiano que aprecian.', '["Pueden conversar por escrito, en varios momentos o con descansos; elijan un nivel de detalle que se sienta seguro.","El afecto físico siempre requiere consentimiento actual; no deben demostrar nada durante la cita."]'::jsonb, '["La pausa está disponible en todo momento. No presionen para revelar, decidir, perdonar ni definir el vínculo."]'::jsonb, 'Elijan una sola pregunta. No es una prueba ni una sesión terapéutica; pausar o no coincidir no exige una solución inmediata.', true, 91),
  ('92-lo-que-aprendimos-del-pasado', 'Lo que aprendimos del pasado', 'conversaciones-importantes', 'Hablen de una lección general o valor que desean conservar; no es necesario narrar historias íntimas ni dar nombres. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Escucharse acerca de aprendizajes que cada quien decide rescatar de experiencias anteriores con cuidado y claridad, sin evaluar compatibilidad ni forzar acuerdos.', 60, 'baja', 'indistinto', '[]'::jsonb, 'Acuerden mantener la conversación en aprendizajes que hoy sea cómodo compartir.', '["Antes de empezar, acuerden que cualquier persona puede pausar, pasar una pregunta o terminar la conversación.","Elijan una sola puerta de entrada: Hablen de una lección general o valor que desean conservar; no es necesario narrar historias íntimas ni dar nombres.","Escuchen para entender; pregunten antes de aconsejar, debatir o intentar resolver.","Cierren sin exigir una conclusión. Si algo requiere seguimiento, cada quien decide si desea retomarlo otro día."]'::jsonb, '["¿Quieres que te escuche, te pregunte o pensemos opciones juntos?","¿Qué significa para ti aprendizajes que cada quien decide rescatar de experiencias anteriores en situaciones cotidianas?","¿Qué necesitarías para conversar de esto con calma?","¿Hay una parte que prefieres dejar abierta o pensar después?","¿Qué podrías pedir o proponer sin esperar que haya una sola respuesta?"]'::jsonb, 'Compartan algo que aprendieron recientemente de un error pequeño.', '["Pueden conversar por escrito, en varios momentos o con descansos; elijan un nivel de detalle que se sienta seguro.","No pregunten detalles que alguien no ofreció ni comparen relaciones pasadas."]'::jsonb, '["La pausa está disponible en todo momento. No presionen para revelar, decidir, perdonar ni definir el vínculo."]'::jsonb, 'Elijan una sola pregunta. No es una prueba ni una sesión terapéutica; pausar o no coincidir no exige una solución inmediata.', true, 92),
  ('93-que-nos-hace-sentir-escuchados', 'Qué nos hace sentir escuchados', 'conversaciones-importantes', 'Cada quien comparte una conducta sencilla que ayuda: mirar, no interrumpir, preguntar o dejar silencio. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Escucharse acerca de señales de escucha y respuestas que resultan útiles con cuidado y claridad, sin evaluar compatibilidad ni forzar acuerdos.', 45, 'baja', 'indistinto', '[]'::jsonb, 'Elijan una pregunta y aclaren si quieren consejos, preguntas o solo escucha.', '["Antes de empezar, acuerden que cualquier persona puede pausar, pasar una pregunta o terminar la conversación.","Elijan una sola puerta de entrada: Cada quien comparte una conducta sencilla que ayuda: mirar, no interrumpir, preguntar o dejar silencio.","Escuchen para entender; pregunten antes de aconsejar, debatir o intentar resolver.","Cierren sin exigir una conclusión. Si algo requiere seguimiento, cada quien decide si desea retomarlo otro día."]'::jsonb, '["¿Qué significa para ti señales de escucha y respuestas que resultan útiles en situaciones cotidianas?","¿Qué necesitarías para conversar de esto con calma?","¿Hay una parte que prefieres dejar abierta o pensar después?","¿Qué podrías pedir o proponer sin esperar que haya una sola respuesta?","¿Qué te ayudaría a cerrar el tema por hoy con tranquilidad?"]'::jsonb, 'Practiquen escuchar una preferencia cotidiana durante dos minutos.', '["Pueden conversar por escrito, en varios momentos o con descansos; elijan un nivel de detalle que se sienta seguro.","El contacto visual no es obligatorio; la escucha puede verse de distintas formas."]'::jsonb, '["La pausa está disponible en todo momento. No presionen para revelar, decidir, perdonar ni definir el vínculo."]'::jsonb, 'Elijan una sola pregunta. No es una prueba ni una sesión terapéutica; pausar o no coincidir no exige una solución inmediata.', true, 93),
  ('94-nuestra-relacion-con-la-familia', 'Nuestra relación con la familia', 'conversaciones-importantes', 'Cada quien puede compartir qué tipo de contacto familiar le resulta cómodo, dejando fuera historias y datos que prefiera reservar. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Escucharse acerca de formas personales de cuidar vínculos familiares y privacidad con cuidado y claridad, sin evaluar compatibilidad ni forzar acuerdos.', 60, 'baja', 'indistinto', '[]'::jsonb, 'Definan límites de privacidad antes de hablar de otras personas.', '["Antes de empezar, acuerden que cualquier persona puede pausar, pasar una pregunta o terminar la conversación.","Elijan una sola puerta de entrada: Cada quien puede compartir qué tipo de contacto familiar le resulta cómodo, dejando fuera historias y datos que prefiera reservar.","Escuchen para entender; pregunten antes de aconsejar, debatir o intentar resolver.","Cierren sin exigir una conclusión. Si algo requiere seguimiento, cada quien decide si desea retomarlo otro día."]'::jsonb, '["¿Qué necesitarías para conversar de esto con calma?","¿Hay una parte que prefieres dejar abierta o pensar después?","¿Qué podrías pedir o proponer sin esperar que haya una sola respuesta?","¿Qué te ayudaría a cerrar el tema por hoy con tranquilidad?","¿Qué límite o pausa quieres que respetemos durante esta charla?"]'::jsonb, 'Hablen de tradiciones generales que disfrutan o prefieren evitar.', '["Pueden conversar por escrito, en varios momentos o con descansos; elijan un nivel de detalle que se sienta seguro.","No evalúen familias ni revelen secretos de terceros; cualquiera puede cambiar de tema."]'::jsonb, '["La pausa está disponible en todo momento. No presionen para revelar, decidir, perdonar ni definir el vínculo."]'::jsonb, 'Elijan una sola pregunta. No es una prueba ni una sesión terapéutica; pausar o no coincidir no exige una solución inmediata.', true, 94),
  ('95-como-cuidamos-nuestra-independencia', 'Cómo cuidamos nuestra independencia', 'conversaciones-importantes', 'Conversen sobre actividades, amistades o tiempos individuales que hacen bien, y cómo comunicar planes con consideración. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Escucharse acerca de espacios y decisiones personales que cada quien quiere conservar con cuidado y claridad, sin evaluar compatibilidad ni forzar acuerdos.', 60, 'baja', 'indistinto', '[]'::jsonb, 'Mantengan la conversación en preferencias actuales y no exijan compartir calendarios privados.', '["Antes de empezar, acuerden que cualquier persona puede pausar, pasar una pregunta o terminar la conversación.","Elijan una sola puerta de entrada: Conversen sobre actividades, amistades o tiempos individuales que hacen bien, y cómo comunicar planes con consideración.","Escuchen para entender; pregunten antes de aconsejar, debatir o intentar resolver.","Cierren sin exigir una conclusión. Si algo requiere seguimiento, cada quien decide si desea retomarlo otro día."]'::jsonb, '["¿Hay una parte que prefieres dejar abierta o pensar después?","¿Qué podrías pedir o proponer sin esperar que haya una sola respuesta?","¿Qué te ayudaría a cerrar el tema por hoy con tranquilidad?","¿Qué límite o pausa quieres que respetemos durante esta charla?","¿Quieres que te escuche, te pregunte o pensemos opciones juntos?"]'::jsonb, 'Cada quien nombra una actividad que disfruta hacer a solas.', '["Pueden conversar por escrito, en varios momentos o con descansos; elijan un nivel de detalle que se sienta seguro.","La independencia no es castigo ni señal de rechazo; eviten pedir contraseñas, ubicaciones o pruebas."]'::jsonb, '["La pausa está disponible en todo momento. No presionen para revelar, decidir, perdonar ni definir el vínculo."]'::jsonb, 'Elijan una sola pregunta. No es una prueba ni una sesión terapéutica; pausar o no coincidir no exige una solución inmediata.', true, 95),
  ('96-proyectos-y-suenos-a-futuro', 'Proyectos y sueños a futuro', 'conversaciones-importantes', 'Cada persona comparte un deseo y qué parte le gustaría explorar; dejen las decisiones y fechas para cuando ambos estén listos. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Escucharse acerca de ideas futuras que pueden imaginarse sin convertirlas en compromisos con cuidado y claridad, sin evaluar compatibilidad ni forzar acuerdos.', 60, 'baja', 'indistinto', '[]'::jsonb, 'Acuerden hablar en términos de posibilidades y no asumir un futuro compartido obligatorio.', '["Antes de empezar, acuerden que cualquier persona puede pausar, pasar una pregunta o terminar la conversación.","Elijan una sola puerta de entrada: Cada persona comparte un deseo y qué parte le gustaría explorar; dejen las decisiones y fechas para cuando ambos estén listos.","Escuchen para entender; pregunten antes de aconsejar, debatir o intentar resolver.","Cierren sin exigir una conclusión. Si algo requiere seguimiento, cada quien decide si desea retomarlo otro día."]'::jsonb, '["¿Qué podrías pedir o proponer sin esperar que haya una sola respuesta?","¿Qué te ayudaría a cerrar el tema por hoy con tranquilidad?","¿Qué límite o pausa quieres que respetemos durante esta charla?","¿Quieres que te escuche, te pregunte o pensemos opciones juntos?","¿Qué significa para ti ideas futuras que pueden imaginarse sin convertirlas en compromisos en situaciones cotidianas?"]'::jsonb, 'Imaginen una actividad que les gustaría hacer en algún momento, sin fijar fecha.', '["Pueden conversar por escrito, en varios momentos o con descansos; elijan un nivel de detalle que se sienta seguro.","Los sueños individuales pueden diferir; no conviertan la conversación en promesa o ultimátum."]'::jsonb, '["La pausa está disponible en todo momento. No presionen para revelar, decidir, perdonar ni definir el vínculo."]'::jsonb, 'Elijan una sola pregunta. No es una prueba ni una sesión terapéutica; pausar o no coincidir no exige una solución inmediata.', true, 96),
  ('97-como-actuar-cuando-uno-tiene-un-mal-dia', 'Cómo actuar cuando uno tiene un mal día', 'conversaciones-importantes', 'Compartan opciones como escuchar, ofrecer espacio, ayudar con una tarea pequeña o preguntar antes de actuar. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Escucharse acerca de apoyos concretos que cada quien puede pedir en un día pesado con cuidado y claridad, sin evaluar compatibilidad ni forzar acuerdos.', 45, 'baja', 'indistinto', '[]'::jsonb, 'Asegúrense de hablar de preferencias, no de resolver un problema actual sin invitación.', '["Antes de empezar, acuerden que cualquier persona puede pausar, pasar una pregunta o terminar la conversación.","Elijan una sola puerta de entrada: Compartan opciones como escuchar, ofrecer espacio, ayudar con una tarea pequeña o preguntar antes de actuar.","Escuchen para entender; pregunten antes de aconsejar, debatir o intentar resolver.","Cierren sin exigir una conclusión. Si algo requiere seguimiento, cada quien decide si desea retomarlo otro día."]'::jsonb, '["¿Qué te ayudaría a cerrar el tema por hoy con tranquilidad?","¿Qué límite o pausa quieres que respetemos durante esta charla?","¿Quieres que te escuche, te pregunte o pensemos opciones juntos?","¿Qué significa para ti apoyos concretos que cada quien puede pedir en un día pesado en situaciones cotidianas?","¿Qué necesitarías para conversar de esto con calma?"]'::jsonb, 'Cada quien elige una frase que le ayuda cuando está cansado.', '["Pueden conversar por escrito, en varios momentos o con descansos; elijan un nivel de detalle que se sienta seguro.","El apoyo no sustituye ayuda profesional ni obliga a estar disponible en todo momento."]'::jsonb, '["La pausa está disponible en todo momento. No presionen para revelar, decidir, perdonar ni definir el vínculo."]'::jsonb, 'Elijan una sola pregunta. No es una prueba ni una sesión terapéutica; pausar o no coincidir no exige una solución inmediata.', true, 97),
  ('98-habitos-que-queremos-mejorar', 'Hábitos que queremos mejorar', 'conversaciones-importantes', 'Cada quien puede elegir un hábito propio y una manera amable de recordarlo, o mantenerlo privado si así lo prefiere. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Escucharse acerca de cambios pequeños que cada quien quiere probar por sí mismo con cuidado y claridad, sin evaluar compatibilidad ni forzar acuerdos.', 45, 'baja', 'indistinto', '[]'::jsonb, 'Enfoquen la conversación en metas propias y acotadas; no hagan una lista de defectos del otro.', '["Antes de empezar, acuerden que cualquier persona puede pausar, pasar una pregunta o terminar la conversación.","Elijan una sola puerta de entrada: Cada quien puede elegir un hábito propio y una manera amable de recordarlo, o mantenerlo privado si así lo prefiere.","Escuchen para entender; pregunten antes de aconsejar, debatir o intentar resolver.","Cierren sin exigir una conclusión. Si algo requiere seguimiento, cada quien decide si desea retomarlo otro día."]'::jsonb, '["¿Qué límite o pausa quieres que respetemos durante esta charla?","¿Quieres que te escuche, te pregunte o pensemos opciones juntos?","¿Qué significa para ti cambios pequeños que cada quien quiere probar por sí mismo en situaciones cotidianas?","¿Qué necesitarías para conversar de esto con calma?","¿Hay una parte que prefieres dejar abierta o pensar después?"]'::jsonb, 'Compartan un hábito neutral que les gustaría practicar una vez.', '["Pueden conversar por escrito, en varios momentos o con descansos; elijan un nivel de detalle que se sienta seguro.","No diagnostiquen ni supervisen al otro; cada quien define su propio cambio."]'::jsonb, '["La pausa está disponible en todo momento. No presionen para revelar, decidir, perdonar ni definir el vínculo."]'::jsonb, 'Elijan una sola pregunta. No es una prueba ni una sesión terapéutica; pausar o no coincidir no exige una solución inmediata.', true, 98),
  ('99-que-tipo-de-relacion-queremos-construir', 'Qué tipo de relación queremos construir', 'conversaciones-importantes', 'Cada quien puede nombrar una cualidad que valora y una pregunta que todavía está explorando, sin definir el vínculo hoy. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Escucharse acerca de expectativas, valores y ritmos para un vínculo elegido por ambos con cuidado y claridad, sin evaluar compatibilidad ni forzar acuerdos.', 60, 'baja', 'indistinto', '[]'::jsonb, 'Acuerden que la conversación no exige una etiqueta ni una decisión; elijan solo una pregunta.', '["Antes de empezar, acuerden que cualquier persona puede pausar, pasar una pregunta o terminar la conversación.","Elijan una sola puerta de entrada: Cada quien puede nombrar una cualidad que valora y una pregunta que todavía está explorando, sin definir el vínculo hoy.","Escuchen para entender; pregunten antes de aconsejar, debatir o intentar resolver.","Cierren sin exigir una conclusión. Si algo requiere seguimiento, cada quien decide si desea retomarlo otro día."]'::jsonb, '["¿Quieres que te escuche, te pregunte o pensemos opciones juntos?","¿Qué significa para ti expectativas, valores y ritmos para un vínculo elegido por ambos en situaciones cotidianas?","¿Qué necesitarías para conversar de esto con calma?","¿Hay una parte que prefieres dejar abierta o pensar después?","¿Qué podrías pedir o proponer sin esperar que haya una sola respuesta?"]'::jsonb, 'Compartan qué cualidad agradecen en cualquier relación significativa.', '["Pueden conversar por escrito, en varios momentos o con descansos; elijan un nivel de detalle que se sienta seguro.","No hay cuestionario de compatibilidad ni conclusión psicológica; pueden pausar o dejar una respuesta pendiente."]'::jsonb, '["La pausa está disponible en todo momento. No presionen para revelar, decidir, perdonar ni definir el vínculo."]'::jsonb, 'Elijan una sola pregunta. No es una prueba ni una sesión terapéutica; pausar o no coincidir no exige una solución inmediata.', true, 99),
  ('100-lo-que-nos-gustaria-seguir-descubriendo', 'Lo que nos gustaría seguir descubriendo', 'conversaciones-importantes', 'Cada quien propone un tema, actividad o gusto que le daría curiosidad conocer del otro y eligen si quieren explorarlo. Pueden ajustar la duración o cambiar de idea en cualquier momento.', 'Escucharse acerca de curiosidades que siguen abiertas y ganas de conocerse gradualmente con cuidado y claridad, sin evaluar compatibilidad ni forzar acuerdos.', 45, 'baja', 'indistinto', '[]'::jsonb, 'Elijan temas invitantes y permitan que algo permanezca sin respuesta.', '["Antes de empezar, acuerden que cualquier persona puede pausar, pasar una pregunta o terminar la conversación.","Elijan una sola puerta de entrada: Cada quien propone un tema, actividad o gusto que le daría curiosidad conocer del otro y eligen si quieren explorarlo.","Escuchen para entender; pregunten antes de aconsejar, debatir o intentar resolver.","Cierren sin exigir una conclusión. Si algo requiere seguimiento, cada quien decide si desea retomarlo otro día."]'::jsonb, '["¿Qué significa para ti curiosidades que siguen abiertas y ganas de conocerse gradualmente en situaciones cotidianas?","¿Qué necesitarías para conversar de esto con calma?","¿Hay una parte que prefieres dejar abierta o pensar después?","¿Qué podrías pedir o proponer sin esperar que haya una sola respuesta?","¿Qué te ayudaría a cerrar el tema por hoy con tranquilidad?"]'::jsonb, 'Nombren una actividad nueva que cada quien podría probar por separado.', '["Pueden conversar por escrito, en varios momentos o con descansos; elijan un nivel de detalle que se sienta seguro.","Descubrirse no crea obligación de compartirlo todo ni de avanzar a un ritmo específico."]'::jsonb, '["La pausa está disponible en todo momento. No presionen para revelar, decidir, perdonar ni definir el vínculo."]'::jsonb, 'Elijan una sola pregunta. No es una prueba ni una sesión terapéutica; pausar o no coincidir no exige una solución inmediata.', true, 100)
